import type { CellProvenance } from '@nexus/shared/cell-provenance'
import { CONTENT_COLUMNS, PRIMARY_CONTENT_LOCALE, contentHash } from './content-locale.js'
import { normalizeLanguage, type ContentLanguage } from './content-language.js'
import { canonicalVariantAxis } from './variant-attribute-keys.js'

export type { ContentLanguage } from './content-language.js'
export interface Coordinate { channel: string; market: string; accountId?: string; aliasId?: string }
export type ContentAddress =
  | { tier: 'source' }
  | { tier: 'language'; language: ContentLanguage }
  | { tier: 'pin'; language: ContentLanguage; coordinate: Coordinate }

export interface ResolvedContent {
  value: unknown
  tier: 'pin' | 'language' | 'source' | 'computed'
  language: ContentLanguage
  requested: ContentLanguage
  // LX.12 adds the renderer for this already-designed member in Step 6. No new UI vocabulary here.
  provenance: { member: CellProvenance | 'outdated'; from: string | null }
  translation?: { source: 'manual' | 'ai' | 'translated'; reviewedAt: string | null; outdated: boolean }
}

type Bag = Record<string, unknown>
export interface ContentTranslation extends Bag {
  language: string
  workspaceId?: string | null
  productId?: string
  channelListingId?: string
  attributes?: Bag | null
  source?: 'manual' | 'ai' | 'translated' | null
  sourceHash?: string | null
  reviewedAt?: string | Date | null
}
export interface ContentProduct extends Bag {
  id: string
  workspaceId?: string | null
  parentId?: string | null
  categoryAttributes?: Bag | null
  translations?: ContentTranslation[]
}
export interface ContentListing extends Bag {
  id: string
  productId: string
  workspaceId?: string | null
  coordinate: Coordinate
  /** Hydrated from marketLanguages(channel, code), never inferred from a country map. */
  languages: readonly string[]
  translations?: ContentTranslation[]
}
export interface ResolveContentInput {
  product: ContentProduct
  parent?: ContentProduct | null
  listing?: ContentListing | null
  field: string
  address: { requested: ContentLanguage; coordinate?: Coordinate }
  /** Family-declared localizable attributes, in addition to the four native content fields. */
  localizableKeys?: readonly string[]
  computed?: { value: unknown; language: ContentLanguage; provenance: ResolvedContent['provenance'] }
}

/** The runtime consumers must opt in only after the production shadow gate. Default is off. */
export const contentResolverEnabled = () => process.env.NEXUS_CONTENT_RESOLVER === 'v2'
export const contentField = (field: string) => field === 'name' ? 'title' : field
const present = (value: unknown) => value !== undefined && value !== null && value !== '' && (!Array.isArray(value) || value.length > 0)
const workspace = (row: { workspaceId?: string | null }) => row.workspaceId ?? null
const label = (language: string) => new Intl.DisplayNames(['en'], { type: 'language' }).of(language) ?? language
const primary = () => normalizeLanguage(PRIMARY_CONTENT_LOCALE)

function sourceValue(product: ContentProduct, parent: ContentProduct | null | undefined, field: string): { value: unknown; owner: ContentProduct } | null {
  const column = CONTENT_COLUMNS[field as keyof typeof CONTENT_COLUMNS]
  for (const owner of [product, parent]) {
    if (!owner) continue
    // Family attributes have authored presence (unlike nullable/default native columns).
    // An explicit null/empty on the child must not resurrect a parent's value.
    if (!column && Object.prototype.hasOwnProperty.call(owner.categoryAttributes ?? {}, field) && owner.categoryAttributes?.[field] !== undefined) return { value: owner.categoryAttributes[field], owner }
    let value = column ? owner[column] : owner.categoryAttributes?.[field]
    if (!column && !present(value)) {
      const variations = owner.categoryAttributes?.variations
      const bag = { ...(owner.variantAttributes as Bag ?? {}), ...(variations && typeof variations === 'object' && !Array.isArray(variations) ? variations : {}) }
      value = bag[field]
      if (value === undefined && ['color', 'size', 'style'].includes(field)) {
        const aliases = Object.entries(bag).filter(([key, value]) => canonicalVariantAxis(key) === field && value !== undefined)
        if (new Set(aliases.map(([, value]) => JSON.stringify(value))).size > 1) throw new Error(`Conflicting source variant attributes for ${field}`)
        value = aliases[0]?.[1]
      }
      if (value !== undefined) return { value, owner }
    }
    if (present(value)) return { value, owner }
  }
  return null
}

/** One row-level source fingerprint, shared with Step 4 authoring. No legacy JSON contributes. */
export function contentSourceHash(product: ContentProduct, parent?: ContentProduct | null, localizableKeys: readonly string[] = []): string {
  const fields = [...new Set([...Object.keys(CONTENT_COLUMNS), ...localizableKeys.map(contentField)])].sort()
  return contentHash(Object.fromEntries(fields.map(field => [field, sourceValue(product, parent, field)?.value ?? null])))
}

/** Normalize stored tags in memory only. Prefer a canonical key; reject ambiguous regional siblings. */
function translationIndex(rows: ContentTranslation[] = []): Map<string, ContentTranslation> {
  const index = new Map<string, ContentTranslation>()
  const groups = new Map<string, ContentTranslation[]>()
  for (const row of rows) {
    const language = normalizeLanguage(row.language)
    groups.set(language, [...(groups.get(language) ?? []), row])
  }
  for (const [language, group] of groups) {
    const canonical = group.filter(row => row.language === language)
    const candidates = canonical.length ? canonical : group
    if (candidates.length !== 1) throw new Error(`Ambiguous content translations for ${language}`)
    index.set(language, candidates[0])
  }
  return index
}

function coordinateMatches(a: Coordinate, b: Coordinate): boolean {
  return a.channel === b.channel && a.market === b.market && (a.accountId ?? null) === (b.accountId ?? null) && (a.aliasId ?? null) === (b.aliasId ?? null)
}

function translationValue(row: ContentTranslation | undefined, field: string): unknown {
  if (!row) return undefined
  const column = CONTENT_COLUMNS[field as keyof typeof CONTENT_COLUMNS]
  return column ? row[column] : row.attributes?.[field]
}

function legacyPin(listing: ContentListing, field: string): unknown {
  const columns = {
    title: ['titleOverride', 'title', 'followMasterTitle'],
    description: ['descriptionOverride', 'description', 'followMasterDescription'],
    bulletPoints: ['bulletPointsOverride', null, 'followMasterBulletPoints'],
  } as const
  const spec = columns[field as keyof typeof columns]
  if (!spec) return undefined
  // Follow-master flags govern explicit overrides; the untagged stored columns remain legacy pins (LX.3).
  if (listing[spec[2]] !== true && present(listing[spec[0]])) return listing[spec[0]]
  return spec[1] ? listing[spec[1]] : undefined
}

function resolver(input: Omit<ResolveContentInput, 'field' | 'address' | 'computed'>) {
  const { product, parent, listing, localizableKeys = [] } = input
  if (parent && (product.parentId !== parent.id || workspace(parent) !== workspace(product))) throw new Error('Content parent does not belong to this product/workspace.')
  if (listing && (listing.productId !== product.id || workspace(listing) !== workspace(product))) throw new Error('Content listing does not belong to this product/workspace.')
  const owners = [product, parent].filter((owner): owner is ContentProduct => !!owner)
  const translations = owners.map(owner => translationIndex((owner.translations ?? []).filter(row => workspace(row) === workspace(owner) && (!row.productId || row.productId === owner.id))))
  const pins = translationIndex((listing?.translations ?? []).filter(row => workspace(row) === workspace(product) && (!row.channelListingId || row.channelListingId === listing?.id)))
  const sourceLanguage = primary()
  const hashes = new Map<string, string>()
  const allowed = new Set([...Object.keys(CONTENT_COLUMNS), ...localizableKeys.map(contentField)])

  return (fieldInput: string, address: ResolveContentInput['address'], computed?: ResolveContentInput['computed']): ResolvedContent => {
    const field = contentField(fieldInput), requested = normalizeLanguage(address.requested)
    if (!allowed.has(field)) throw new Error(`Field ${field} is not declared localizable.`)
    const result = (value: unknown, tier: ResolvedContent['tier'], language: string, member: ResolvedContent['provenance']['member'], from: string | null): ResolvedContent => ({ value, tier, language, requested, provenance: { member, from } })
    const translated = (row: ContentTranslation, value: unknown, tier: 'pin' | 'language', owner: ContentProduct): ResolvedContent => {
      const source = row.source ?? 'manual'
      const reviewedAt = row.reviewedAt ? new Date(row.reviewedAt).toISOString() : null
      if (row.sourceHash && !hashes.has(owner.id)) hashes.set(owner.id, contentSourceHash(owner, owner === product ? parent : null, localizableKeys))
      const outdated = !!row.sourceHash && row.sourceHash !== hashes.get(owner.id)
      const machine = source === 'ai' || source === 'translated'
      const member = outdated ? machine && !reviewedAt ? 'aiStale' : 'outdated' : machine && !reviewedAt ? 'ai' : tier === 'pin' ? 'pinned' : address.coordinate || owner !== product ? 'inherited' : 'own'
      return { ...result(value, tier, requested, member, tier === 'pin' ? listing!.id : `${label(requested)} · shared`), translation: { source, reviewedAt, outdated } }
    }
    if (address.coordinate && listing) {
      if (!coordinateMatches(listing.coordinate, address.coordinate)) throw new Error('Content listing coordinate does not match the requested address.')
      if (!listing.languages.length) throw new Error('Content listing needs its market languages.')
      const pin = pins.get(requested), value = translationValue(pin, field)
      if (present(value)) return translated(pin!, value, 'pin', product)
      if (requested === normalizeLanguage(listing.languages[0])) {
        const legacy = legacyPin(listing, field)
        if (present(legacy)) return result(legacy, 'pin', requested, 'pinned', listing.id)
      }
    }
    if (requested !== sourceLanguage) for (const [i, owner] of owners.entries()) {
      const row = translations[i].get(requested), value = translationValue(row, field)
      if (present(value)) return translated(row!, value, 'language', owner)
    }
    const source = sourceValue(product, parent, field)
    if (source) return result(source.value, 'source', sourceLanguage, address.coordinate || requested !== sourceLanguage || source.owner !== product ? 'inherited' : 'own', `${label(sourceLanguage)} · source`)
    if (computed && present(computed.value)) return { ...result(computed.value, 'computed', normalizeLanguage(computed.language), computed.provenance.member, computed.provenance.from) }
    return result(null, 'computed', sourceLanguage, 'inherited', null)
  }
}

/** Pure: consumes hydrated rows only. Never reads localizedContent, overrideData or outbound platformAttributes. */
export function resolveContent(input: ResolveContentInput): ResolvedContent {
  return resolver(input)(input.field, input.address, input.computed)
}

/** Mapping source paths keep their explicit language/link semantics, but never walk legacy JSON. */
export function contentPathAddress(path: string, requested: string, localizableKeys: readonly string[] = []): { field: string; requested: string; tail: string[] } | null {
  const parts = path.replace(/\{locale\}/g, requested).split('.')
  let language = requested
  if (parts[0] === 'localizedContent') { parts.shift(); language = parts.shift() ?? '' }
  else if (['categoryAttributes', 'variantAttributes'].includes(parts[0])) parts.shift()
  const field = contentField(parts.shift() ?? '')
  if (![...Object.keys(CONTENT_COLUMNS), ...localizableKeys].includes(field)) return null
  return { field, requested: normalizeLanguage(language), tail: parts }
}

export function resolveContentPath(input: Omit<ResolveContentInput, 'field'> & { path: string }): ResolvedContent | null {
  const path = contentPathAddress(input.path, input.address.requested, input.localizableKeys)
  if (!path) return null
  const resolved = resolveContent({ ...input, field: path.field, address: { ...input.address, requested: path.requested } })
  let value = resolved.value
  for (const key of path.tail) value = value && typeof value === 'object' ? (value as Bag)[key] ?? null : null
  return { ...resolved, value }
}

/** One translation index per family member; all fields × addresses reuse it. No database queries. */
export function resolveContentBatch(input: {
  members: Array<Omit<ResolveContentInput, 'field' | 'address' | 'computed'>>
  fields: readonly string[]
  addresses: ReadonlyArray<ResolveContentInput['address']>
}): Array<{ productId: string; address: ResolveContentInput['address']; fields: Record<string, ResolvedContent> }> {
  return input.members.flatMap(member => {
    const resolve = resolver(member)
    return input.addresses.map(address => ({ productId: member.product.id, address: { ...address, requested: normalizeLanguage(address.requested) }, fields: Object.fromEntries(input.fields.map(field => [field, resolve(field, address)])) }))
  })
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { contentResolverEnabled, contentSourceHash, resolveContent, resolveContentBatch, type ContentProduct, type ResolveContentInput } from './content-resolver.js'

const product = (): ContentProduct => ({ id: 'p', parentId: null, name: 'Fonte', description: 'Descrizione', bulletPoints: ['Uno'], keywords: ['fonte'], categoryAttributes: { material: 'pelle' }, translations: [] })
const coordinate = { channel: 'AMAZON', market: 'BE', accountId: 'a' }
const listing = () => ({ id: 'l', productId: 'p', coordinate, languages: ['nl', 'fr'], title: 'Nederlands', description: 'Beschrijving' })
const input = (extra: Partial<ResolveContentInput> = {}): ResolveContentInput => ({ product: product(), field: 'title', address: { requested: 'de' }, ...extra })
afterEach(() => vi.unstubAllEnvs())

describe('LX.7 pure content resolution', () => {
  it('is disabled until an explicit v2 flag is supplied', () => {
    vi.stubEnv('NEXUS_CONTENT_RESOLVER', '')
    expect(contentResolverEnabled()).toBe(false)
    vi.stubEnv('NEXUS_CONTENT_RESOLVER', 'v2')
    expect(contentResolverEnabled()).toBe(true)
  })
  it('returns native source with its actual language on fallback', () => {
    expect(resolveContent(input())).toEqual({ value: 'Fonte', tier: 'source', language: 'it', requested: 'de', provenance: { member: 'inherited', from: 'Italian · source' } })
  })
  it('uses columns for the primary language even when a translation row exists', () => {
    const p = product(); p.translations = [{ language: 'it', name: 'Stale copy' }]
    expect(resolveContent(input({ product: p, address: { requested: 'it_IT' } }))).toMatchObject({ value: 'Fonte', tier: 'source', language: 'it', requested: 'it', provenance: { member: 'own' } })
  })
  it('reads a regional table key in memory and leaves every input byte unchanged', () => {
    const p = product(); p.translations = [{ language: 'DE-de', name: 'Titel', source: 'manual' }]
    const before = JSON.stringify(p)
    expect(resolveContent(input({ product: p, address: { requested: 'de_DE' } }))).toMatchObject({ value: 'Titel', tier: 'language', language: 'de', requested: 'de', provenance: { member: 'own' } })
    expect(JSON.stringify(p)).toBe(before)
  })
  it('never touches legacy JSON or the outbound and factual bags', () => {
    const p = product(), l = listing()
    Object.defineProperty(p, 'localizedContent', { get: () => { throw new Error('Legacy read') } })
    for (const key of ['platformAttributes', 'overrideData']) Object.defineProperty(l, key, { get: () => { throw new Error('Outbound read') } })
    expect(resolveContent(input({ product: p, listing: l, address: { requested: 'fr', coordinate } })).value).toBe('Fonte')
  })
  it.each(['nl', 'nl-BE'])('keeps the default-language listing title and description as legacy pins: %s', requested => {
    for (const [field, value] of [['title', 'Nederlands'], ['description', 'Beschrijving']]) expect(resolveContent(input({ listing: listing(), field, address: { requested, coordinate } }))).toMatchObject({ value, tier: 'pin', language: 'nl', provenance: { member: 'pinned' } })
  })
  it('does not serve a Dutch legacy pin as French', () => {
    const p = product(); p.translations = [{ language: 'fr', name: 'Français' }]
    expect(resolveContent(input({ product: p, listing: listing(), address: { requested: 'fr', coordinate } }))).toMatchObject({ value: 'Français', tier: 'language', language: 'fr', provenance: { member: 'inherited' } })
  })
  it('prefers an explicit pin row to legacy pins and the language tier', () => {
    const p = product(); p.translations = [{ language: 'nl', name: 'Shared' }]
    const l = { ...listing(), translations: [{ language: 'nl', name: 'Pin', channelListingId: 'l' }] }
    expect(resolveContent(input({ product: p, listing: l, address: { requested: 'nl', coordinate } }))).toMatchObject({ value: 'Pin', tier: 'pin' })
  })
  it('uses explicit legacy overrides when inheritance was broken', () => {
    const l = { ...listing(), followMasterTitle: false, titleOverride: 'Override' }
    expect(resolveContent(input({ listing: l, address: { requested: 'nl', coordinate } })).value).toBe('Override')
    l.followMasterTitle = true
    expect(resolveContent(input({ listing: l, address: { requested: 'nl', coordinate } })).value).toBe('Nederlands')
  })
  it('uses child then parent within each tier, with language ahead of source', () => {
    const parent = product(), child = { ...product(), id: 'child', parentId: parent.id, name: 'Child source' }
    parent.translations = [{ language: 'de', name: 'Eltern', description: 'Beschreibung' }]
    child.translations = [{ language: 'de', name: 'Kind', description: null, bulletPoints: [] }]
    expect(resolveContent(input({ product: child, parent })).value).toBe('Kind')
    expect(resolveContent(input({ product: child, parent, field: 'description' }))).toMatchObject({ value: 'Beschreibung', tier: 'language', provenance: { member: 'inherited' } })
    child.translations = []
    expect(resolveContent(input({ product: child, parent })).value).toBe('Eltern')
  })
  it('falls back field by field; schema-default empty lists do not hide source', () => {
    const p = product(); p.translations = [{ language: 'de', name: 'Titel', description: '', bulletPoints: [], keywords: null }]
    for (const field of ['description', 'bulletPoints', 'keywords']) expect(resolveContent(input({ product: p, field })).tier).toBe('source')
  })
  it('limits custom translations to family-declared localizable fields', () => {
    const p = product(); p.translations = [{ language: 'de', attributes: { material: 'Leder', price: 99 } }]
    expect(resolveContent(input({ product: p, field: 'material', localizableKeys: ['material'] })).value).toBe('Leder')
    expect(() => resolveContent(input({ product: p, field: 'price' }))).toThrow('not declared localizable')
  })
  it('preserves a family-declared field supplied by native variant attributes', () => {
    const p = { ...product(), variantAttributes: { style: 'Da motociclista' } }
    expect(resolveContent(input({ product: p, field: 'style', localizableKeys: ['style'] }))).toMatchObject({ value: 'Da motociclista', tier: 'source', language: 'it' })
    expect(resolveContent(input({ product: { ...product(), variantAttributes: { Style: 'Racing' } }, field: 'style', localizableKeys: ['style'] })).value).toBe('Racing')
  })
  it('preserves an explicit child attribute clear instead of resurrecting parent text', () => {
    const parent = { ...product(), categoryAttributes: { weave_type: 'Not applicable' } }
    const child = { ...product(), id: 'child', parentId: parent.id, categoryAttributes: { weave_type: null }, variantAttributes: { weave_type: 'Obsolete alias' } }
    expect(resolveContent(input({ product: child, parent, field: 'weave_type', localizableKeys: ['weave_type'] }))).toMatchObject({ value: null, tier: 'source', language: 'it' })
  })
  it('checks an inherited translation against its authoring owner’s source', () => {
    const parent = product(), child = { ...product(), id: 'child', parentId: parent.id, name: 'Different child source' }
    parent.translations = [{ language: 'de', name: 'Eltern', sourceHash: contentSourceHash(parent), source: 'manual' }]
    expect(resolveContent(input({ product: child, parent })).translation?.outdated).toBe(false)
    parent.name = 'Changed parent source'
    expect(resolveContent(input({ product: child, parent })).translation?.outdated).toBe(true)
  })
  it.each(['manual', 'ai', 'translated'] as const)('carries review and source freshness for %s', source => {
    const p = product(), sourceHash = contentSourceHash(p), reviewedAt = new Date('2026-09-01T00:00:00Z')
    p.translations = [{ language: 'de', name: 'Titel', source, sourceHash, reviewedAt }]
    expect(resolveContent(input({ product: p }))).toMatchObject({ translation: { source, reviewedAt: reviewedAt.toISOString(), outdated: false } })
    p.name = 'Changed source'
    expect(resolveContent(input({ product: p }))).toMatchObject({ provenance: { member: 'outdated' }, translation: { outdated: true } })
  })
  it.each(['ai', 'translated'] as const)('keeps unreviewed %s visibly machine-authored, including staleness', source => {
    const p = product(); p.translations = [{ language: 'de', name: 'Titel', source, sourceHash: contentSourceHash(p) }]
    expect(resolveContent(input({ product: p })).provenance.member).toBe('ai')
    p.name = 'New'
    expect(resolveContent(input({ product: p })).provenance.member).toBe('aiStale')
  })
  it('does not invent a source fingerprint or human review for historical translations', () => {
    const p = product(); p.translations = [{ language: 'de', name: 'Titel', source: 'ai' }]
    expect(resolveContent(input({ product: p })).translation).toEqual({ source: 'ai', reviewedAt: null, outdated: false })
  })
  it('lets a computed value answer only after all stored tiers are absent', () => {
    const computed = { value: 'Formula', language: 'de-DE', provenance: { member: 'formula' as const, from: 'formula-id' } }
    expect(resolveContent(input({ computed })).tier).toBe('source')
    expect(resolveContent(input({ product: { id: 'p' }, computed }))).toMatchObject({ value: 'Formula', tier: 'computed', language: 'de', provenance: { member: 'formula' } })
    expect(resolveContent(input({ product: { id: 'p' } })).value).toBeNull()
  })
  it('refuses foreign parents, listings and coordinates', () => {
    expect(() => resolveContent(input({ parent: { id: 'other' } }))).toThrow('parent')
    expect(() => resolveContent(input({ listing: { ...listing(), workspaceId: 'foreign' } }))).toThrow('listing')
    for (const change of [{ channel: 'EBAY' }, { market: 'DE' }, { accountId: 'other' }, { aliasId: 'alias' }]) expect(() => resolveContent(input({ listing: listing(), address: { requested: 'nl', coordinate: { ...coordinate, ...change } } }))).toThrow('coordinate')
  })
  it('does not inherit another workspace or product translation', () => {
    const p = product(); p.translations = [{ language: 'de', name: 'Foreign', workspaceId: 'other' }, { language: 'de', name: 'Wrong product', productId: 'other' }]
    expect(resolveContent(input({ product: p })).tier).toBe('source')
  })
  it('gives canonical language keys precedence over regional keys', () => {
    const rows = [{ language: 'de-DE', name: 'Regional' }, { language: 'de', name: 'Canonical' }]
    for (const translations of [rows, [...rows].reverse()]) expect(resolveContent(input({ product: { ...product(), translations } })).value).toBe('Canonical')
  })
  it('refuses ambiguous regional-only translations instead of depending on row order', () => {
    const p = { ...product(), translations: [{ language: 'de-DE', name: 'A' }, { language: 'de-AT', name: 'B' }] }
    expect(() => resolveContent(input({ product: p }))).toThrow('Ambiguous')
  })
  it('batch returns every member × language × field with the same values as scalar resolution', () => {
    const p = product(), child = { ...product(), id: 'child', parentId: p.id }
    p.translations = [{ language: 'de', name: 'Titel' }]
    const members = [{ product: p }, { product: child, parent: p }], fields = ['title', 'description', 'bulletPoints', 'keywords'], addresses = ['de-DE', 'it', 'fr'].map(requested => ({ requested }))
    const batch = resolveContentBatch({ members, fields, addresses })
    expect(batch).toHaveLength(6)
    for (const row of batch) for (const field of fields) expect(row.fields[field]).toEqual(resolveContent({ ...members.find(m => m.product.id === row.productId)!, field, address: row.address }))
  })
})

