  // ── AssetUsage ──────────────────────────────────────────────

  fastify.post('/products/:id/asset-usages', async (request, reply) => {
    const { id: productId } = request.params as { id: string }
    const body = request.body as {
      assetId?: string
      role?: string
      sortOrder?: number
    }
