  // ── MC.2.1 — AssetTag CRUD ─────────────────────────────────

  // List all tags. Includes asset count alongside the existing
  // product/order counts so the operator can see which tags are
  // actually used by the DAM. This duplicates a thin slice of the
  // /tags endpoint that already exists elsewhere; consolidating is a
  // follow-up. Returning here keeps /marketing/content's network
  // surface contained.
  fastify.get('/asset-tags', async () => {
    const tags = await prisma.tag.findMany({
      orderBy: { name: 'asc' },
      include: {
        _count: {
          select: { assets: true, products: true, orders: true },
        },
      },
    })
    return { tags }
  })

  // Replace the tag set on a DigitalAsset. Body is { tagIds: [...] }
  // or { tagNames: [...] } — name form auto-creates tags that don't
  // yet exist (operator-friendly; common-case is "type a new tag in
  // the picker"). Returns the updated tag list so the drawer can
  // render without re-fetching.
  fastify.put('/assets/:id/tags', async (request, reply) => {
    const { id: assetId } = request.params as { id: string }
    const body = request.body as {
      tagIds?: string[]
      tagNames?: string[]
    }
    const asset = await prisma.digitalAsset.findUnique({
      where: { id: assetId },
      select: { id: true },
    })
    if (!asset)
      return reply.code(404).send({ error: 'asset not found' })

    const idSet = new Set(body.tagIds ?? [])

    // Resolve names → ids, creating any that don't exist. createMany
    // with skipDuplicates would be cleaner but doesn't return rows;
    // upsert one-by-one is fine here because the picker shouldn't
    // routinely create more than a handful.
    if (body.tagNames?.length) {
      for (const rawName of body.tagNames) {
        const name = rawName.trim()
        if (!name) continue
        const existing = await prisma.tag.findUnique({ where: { workspace_name: workspaceKey({ name: name }) } })
        if (existing) {
          idSet.add(existing.id)
        } else {
          const created = await prisma.tag.create({ data: { name } })
          idSet.add(created.id)
        }
      }
    }

    const tagIds = [...idSet]

    // Replace strategy — drop existing rows then create the new set.
    // Wrapped in a transaction so partial failures roll back; the
    // operator sees either the old set or the new, never a mix.
    await prisma.$transaction([
      prisma.assetTag.deleteMany({ where: { assetId } }),
      ...(tagIds.length
        ? [
            prisma.assetTag.createMany({
              data: tagIds.map((tagId) => ({ assetId, tagId })),
              skipDuplicates: true,
            }),
          ]
        : []),
    ])

    const tags = await prisma.tag.findMany({
      where: { id: { in: tagIds } },
      orderBy: { name: 'asc' },
    })
    return { tags }
  })

  // ── MC.6.4 — Per-channel preview pane ──────────────────────

  // Returns the channel variant URLs with the picked locale overlay
  // spliced in. The preview pane on the drawer renders these with
  // channel-specific frames (Amazon hero, eBay gallery, Shopify
  // product card, OG card, IG square/story).
  fastify.get<{
    Params: { id: string }
    Querystring: { locale?: string; profile?: string }
  }>('/assets/:id/preview', async (request, reply) => {
    const id = request.params.id.startsWith('da_')
      ? request.params.id.slice(3)
      : request.params.id
    const locale = request.query.locale ?? 'it-IT'

    const asset = await prisma.digitalAsset.findUnique({
      where: { id },
      select: {
        id: true,
        url: true,
        type: true,
        storageProvider: true,
        storageId: true,
        localeOverlays: {
          where: { enabled: true },
        },
      },
    })
    if (!asset) return reply.code(404).send({ error: 'asset not found' })

    const { buildAllVariants } = await import(
      '../services/channel-variants.service.js'
    )
    const { pickOverlayForLocale, applyOverlayToUrl } = await import(
      '../services/asset-locale-overlay.service.js'
    )

    const validProfile =
      request.query.profile === 'eco' ||
      request.query.profile === 'balanced' ||
      request.query.profile === 'hd' ||
      request.query.profile === 'lossless'
        ? request.query.profile
        : undefined
    const overlay = pickOverlayForLocale(asset.localeOverlays, locale)
    const variants = buildAllVariants(asset, validProfile).map((v) => ({
      ...v,
      url: v.url ? applyOverlayToUrl(v.url, overlay) : null,
    }))

    return {
      assetId: id,
      locale,
      profile: validProfile ?? null,
      activeOverlay: overlay
        ? { id: overlay.id, locale: overlay.locale, text: overlay.text }
        : null,
      variants,
    }
  })

  // ── MC.6.3 — AssetLocaleOverlay CRUD ───────────────────────

  // List overlays for a single asset. The drawer fetches this on
