  // ── MC.2.2 — AssetFolder CRUD + tree ───────────────────────

  // Returns the entire folder tree as a flat list with parentId. The
  // operator's tree usually fits in a single response (< 1k folders
  // even at large catalogs), and the client renders the tree
  // structure off the parentId pointers. If the workspace ever
  // outgrows that, MC.2-followup paginates by depth.
  fastify.get('/asset-folders', async () => {
    const folders = await prisma.assetFolder.findMany({
      orderBy: [{ parentId: 'asc' }, { order: 'asc' }, { name: 'asc' }],
      include: {
        _count: { select: { assets: true, children: true } },
      },
    })
    return { folders }
  })

  fastify.post('/asset-folders', async (request, reply) => {
    const body = request.body as {
      name?: string
      parentId?: string | null
      order?: number
    }
    if (!body.name?.trim())
      return reply.code(400).send({ error: 'name is required' })

    if (body.parentId) {
      const parent = await prisma.assetFolder.findUnique({
        where: { id: body.parentId },
        select: { id: true },
      })
      if (!parent)
        return reply.code(400).send({ error: 'parentId does not exist' })
    }

    const folder = await prisma.assetFolder.create({
      data: {
        name: body.name.trim(),
        parentId: body.parentId ?? null,
        order: typeof body.order === 'number' ? body.order : 0,
      },
    })
    return reply.code(201).send({ folder })
  })

  fastify.patch('/asset-folders/:id', async (request, reply) => {
    const { id } = request.params as { id: string }
    const body = request.body as {
      name?: string
      parentId?: string | null
      order?: number
    }
    const data: Record<string, unknown> = {}
    if (body.name !== undefined) {
      if (!body.name.trim())
        return reply.code(400).send({ error: 'name cannot be empty' })
      data.name = body.name.trim()
    }
    if (body.parentId !== undefined) {
      // Prevent cycles — a folder can't be its own ancestor. Walk
      // up the requested parent's chain; if we hit `id` first, the
      // move would create a cycle.
      if (body.parentId === id)
        return reply
          .code(400)
          .send({ error: 'cannot make a folder its own parent' })
      if (body.parentId) {
        let cursor: string | null = body.parentId
        for (let i = 0; i < 32 && cursor; i++) {
          if (cursor === id)
            return reply.code(400).send({
              error:
                'cycle detected — moving here would put a folder inside its own subtree',
            })
          const parent = await prisma.assetFolder.findUnique({
            where: { id: cursor },
            select: { parentId: true },
          })
          if (!parent) break
          cursor = parent.parentId
        }
      }
      data.parentId = body.parentId ?? null
    }
    if (body.order !== undefined) data.order = body.order
    if (Object.keys(data).length === 0)
      return reply.code(400).send({ error: 'no mutable fields supplied' })
    try {
      const folder = await prisma.assetFolder.update({
        where: { id },
        data,
      })
      return { folder }
    } catch (err: any) {
      if (err?.code === 'P2025')
        return reply.code(404).send({ error: 'folder not found' })
      throw err
    }
  })

  fastify.delete('/asset-folders/:id', async (request, reply) => {
    const { id } = request.params as { id: string }
    try {
      await prisma.assetFolder.delete({ where: { id } })
      return { ok: true, id }
    } catch (err: any) {
      if (err?.code === 'P2025')
        return reply.code(404).send({ error: 'folder not found' })
      throw err
    }
  })

  // ── MC.3.1 — direct upload (multipart) ─────────────────────

  fastify.post('/assets/upload', async (request, reply) => {
    const source = (request.query as { source?: string }).source
    if (source !== undefined && source !== 'nexus') return reply.code(400).send({ error: 'Choose a valid media source.' })
    if (source !== 'nexus') {
      const { defaultShopifyMediaAccount, uploadReadyShopifyAsset, ShopifyMediaError } = await import('../services/shopify/media-library.service.js')
      try {
        const accountId = await defaultShopifyMediaAccount()
        if (accountId) {
          const file = await request.file({ limits: { files: 1, fileSize: 200 * 1024 * 1024 } })
          if (!file) return reply.code(400).send({ error: 'Choose a file to upload.' })
          const buffer = await file.toBuffer()
          if (file.file.truncated) return reply.code(413).send({ error: 'This file exceeds the upload limit.' })
          const result = await uploadReadyShopifyAsset(accountId, buffer, file.filename)
          return reply.code(result.reused ? 200 : 201).send({ asset: result.asset, dedup: result.reused })
        }
      } catch (error) {
        if (error instanceof ShopifyMediaError) return reply.code(error.statusCode).send({ error: error.message })
        if (error instanceof Error && 'code' in error && error.code === 'FST_REQ_FILE_TOO_LARGE') return reply.code(413).send({ error: 'This file exceeds the 200 MB upload limit.' })
        request.log.error({ err: error }, 'Shopify default media upload failed')
        return reply.code(502).send({ error: 'The Shopify upload could not be confirmed. Refresh the media library before retrying.' })
      }
    }
    if (!isCloudinaryConfigured())
      return reply.code(503).send({
        error:
          'Storage is not configured. Set CLOUDINARY_CLOUD_NAME, CLOUDINARY_API_KEY, CLOUDINARY_API_SECRET.',
      })

    const part = await request.file()
    if (!part) return reply.code(400).send({ error: 'no file uploaded' })

    // MC.7.1 — accept video too. The route picks the right Cloudinary
    // resource_type below; a single endpoint keeps the client + dedup
    // path simple for both media types.
    const isVideo = UPLOAD_VIDEO_MIME_TYPES.has(part.mimetype)
    const isImage = UPLOAD_IMAGE_MIME_TYPES.has(part.mimetype)
    if (!isImage && !isVideo)
      return reply.code(400).send({
        error: `unsupported mime type "${part.mimetype}". Allowed: ${[...UPLOAD_IMAGE_MIME_TYPES, ...UPLOAD_VIDEO_MIME_TYPES].join(', ')}`,
      })

    // Pull the multipart fields out of the form-data body. fastify-
    // multipart returns the file as `part`, plus any non-file fields
    // on `part.fields` keyed by name.
    const fields = part.fields as Record<
      string,
      { value: string } | undefined
    >
    const folderId = fields?.folderId?.value || null
    const labelOverride = fields?.label?.value?.trim() || null

    if (folderId) {
      const folder = await prisma.assetFolder.findUnique({
        where: { id: folderId },
        select: { id: true },
      })
      if (!folder)
        return reply.code(400).send({ error: 'folderId does not exist' })
    }

    // Stream-to-buffer with a hard cap. fastify-multipart already has
    // a `limits.fileSize` knob but its enforcement is async and we
    // get a partial buffer back; checking length post-toBuffer is
    // belt-and-braces.
    const buffer = await part.toBuffer()
    // MC.7.1 — videos use the larger MAX_VIDEO_BYTES cap; images stay
    // on the historical MAX_UPLOAD_BYTES so the existing operator
    // expectations don't shift.
    const sizeCap = isVideo ? MAX_VIDEO_BYTES : MAX_UPLOAD_BYTES
    if (buffer.length > sizeCap)
      return reply.code(413).send({
        error: `file exceeds the ${sizeCap} byte limit`,
        size: buffer.length,
      })

    // MC.13.1 — quota check (env-driven). Returns 507 Insufficient
    // Storage when the workspace would breach the hard cap.
    {
      const quota = await checkStorageQuota(buffer.length)
      if (!quota.ok)
        return reply.code(507).send({
          error: `Storage quota exceeded`,
          usedBytes: quota.usedBytes,
          hardCapBytes: quota.hardCap,
          fileSize: buffer.length,
        })
    }

    // MC.3.3 — dedup. Hash the bytes; if we have a row already, file
    // it into the requested folder (if different) and return that.
    // Never re-upload the same bytes to Cloudinary — saves storage
    // cost and keeps publicIds stable so downstream caches hold.
    const contentHash = sha256Hex(buffer)
    const existing = await prisma.digitalAsset.findUnique({
      where: { workspace_contentHash: workspaceKey({ contentHash: contentHash }) },
    })
    if (existing) {
      // If the operator dropped this file into a different folder
      // than where it lived previously, re-file it. Don't overwrite
      // label/alt — the operator's prior work on metadata is more
      // valuable than the latest filename.
      if (folderId && existing.folderId !== folderId) {
        const moved = await prisma.digitalAsset.update({
          where: { id: existing.id },
          data: { folderId },
        })
        return reply
          .code(200)
          .send({ asset: moved, dedup: true, refiled: true })
      }
      return reply.code(200).send({ asset: existing, dedup: true })
    }

    const folder = folderId
      ? `marketing-content/${folderId}`
      : 'marketing-content/unfiled'

    let cloudResult
    try {
      cloudResult = await uploadBufferToCloudinary(buffer, {
        folder,
        resourceType: isVideo ? 'video' : 'image',
      })
    } catch (err) {
      return reply.code(502).send({
        error: 'storage upload failed',
        detail: err instanceof Error ? err.message : 'unknown',
      })
    }

    // MC.3.4 — quality check. Skip for videos in MC.7.1; the spec
    // library is still image-only. MC.7.6 will land a video-specific
    // checker (resolution + duration + bitrate).
    const qualityWarnings = isVideo
      ? []
      : checkAssetQuality({
          width: cloudResult.width,
          height: cloudResult.height,
          mimeType: part.mimetype,
          sizeBytes: cloudResult.bytes,
        })

    let asset
    try {
      asset = await prisma.digitalAsset.create({
        data: {
          label: labelOverride ?? part.filename ?? 'Untitled',
          type: isVideo ? 'video' : 'image',
          mimeType: part.mimetype,
          sizeBytes: cloudResult.bytes,
          storageProvider: 'cloudinary',
          storageId: cloudResult.publicId,
          url: cloudResult.url,
          originalFilename: part.filename ?? null,
          contentHash,
          folderId,
          metadata: {
            width: cloudResult.width,
            height: cloudResult.height,
            format: cloudResult.format,
            // MC.7.6 — video metadata captured up-front so the drawer
            // doesn't need to re-probe Cloudinary on render.
            durationSeconds: cloudResult.durationSeconds ?? null,
            resourceType: cloudResult.resourceType ?? null,
            qualityWarnings: qualityWarnings as unknown as object[],
          },
        },
      })
    } catch (err: any) {
      // Race: a concurrent upload of the same bytes won the unique
      // index. Look up the winning row and return it. Cloudinary
      // upload we just did is now an orphan; cleanup is fire-and-
      // forget — Cloudinary's admin tools / a periodic sweep handle
      // these.
      if (err?.code === 'P2002') {
        const winner = await prisma.digitalAsset.findUnique({
          where: { workspace_contentHash: workspaceKey({ contentHash: contentHash }) },
        })
        if (winner)
          return reply.code(200).send({ asset: winner, dedup: true })
      }
      throw err
    }

    return reply.code(201).send({ asset })
  })

  // MC.3.1 — upload-from-URL.
  //
  // Operator pastes a public URL (Amazon CDN, supplier site, Google
  // Drive direct link) and the server fetches it, validates it, and
  // pushes to Cloudinary. Saves the operator from a download-then-
  // upload roundtrip and lets us auto-import from listings on other
  // marketplaces.
  fastify.post('/assets/upload-url', async (request, reply) => {
    if (!isCloudinaryConfigured())
      return reply.code(503).send({ error: 'Storage is not configured.' })

    const body = request.body as {
      url?: string
      label?: string
      folderId?: string | null
    }
    if (!body.url?.trim())
      return reply.code(400).send({ error: 'url is required' })
    let parsed: URL
    try {
      parsed = new URL(body.url.trim())
    } catch {
      return reply.code(400).send({ error: 'url is not a valid URL' })
    }
    if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:')
      return reply
        .code(400)
        .send({ error: 'url must be http(s)' })

    if (body.folderId) {
      const folder = await prisma.assetFolder.findUnique({
        where: { id: body.folderId },
        select: { id: true },
      })
      if (!folder)
        return reply.code(400).send({ error: 'folderId does not exist' })
    }

    let res: Response
    try {
      res = await fetch(parsed.toString(), {
        // 15s cap; longer fetches go through the bulk flow.
        signal: AbortSignal.timeout(15_000),
        redirect: 'follow',
      })
    } catch (err) {
      return reply.code(502).send({
        error: 'failed to fetch the URL',
        detail: err instanceof Error ? err.message : 'unknown',
      })
    }
    if (!res.ok)
      return reply
        .code(502)
        .send({ error: `source URL returned ${res.status}` })

    const mimeType = res.headers.get('content-type')?.split(';')[0]?.trim()
    const isVideo = mimeType ? UPLOAD_VIDEO_MIME_TYPES.has(mimeType) : false
    const isImage = mimeType ? UPLOAD_IMAGE_MIME_TYPES.has(mimeType) : false
    if (!mimeType || (!isImage && !isVideo))
      return reply
        .code(400)
        .send({ error: `unsupported content-type "${mimeType ?? 'unknown'}"` })

    const arrayBuffer = await res.arrayBuffer()
    const sizeCap = isVideo ? MAX_VIDEO_BYTES : MAX_UPLOAD_BYTES
    if (arrayBuffer.byteLength > sizeCap)
      return reply.code(413).send({
        error: `remote file exceeds the ${sizeCap} byte limit`,
        size: arrayBuffer.byteLength,
      })

    // MC.13.1 — quota check on URL imports too. Cap is the same
    // workspace-level number; URL imports count against the hard
    // cap exactly like multipart uploads.
    {
      const quota = await checkStorageQuota(arrayBuffer.byteLength)
      if (!quota.ok)
        return reply.code(507).send({
          error: 'Storage quota exceeded',
          usedBytes: quota.usedBytes,
          hardCapBytes: quota.hardCap,
          fileSize: arrayBuffer.byteLength,
        })
    }

    const buffer = Buffer.from(arrayBuffer)

    // MC.3.3 — same dedup path as the multipart upload. URL imports
    // are common-case for "I bought stock photos and pasted three
    // links" workflows so the dedup hit is meaningful.
    const contentHash = sha256Hex(buffer)
    const existing = await prisma.digitalAsset.findUnique({
      where: { workspace_contentHash: workspaceKey({ contentHash: contentHash }) },
    })
    if (existing) {
      if (body.folderId && existing.folderId !== body.folderId) {
        const moved = await prisma.digitalAsset.update({
          where: { id: existing.id },
          data: { folderId: body.folderId },
        })
        return reply
          .code(200)
          .send({ asset: moved, dedup: true, refiled: true })
      }
      return reply.code(200).send({ asset: existing, dedup: true })
    }

    const folder = body.folderId
      ? `marketing-content/${body.folderId}`
      : 'marketing-content/unfiled'

    let cloudResult
    try {
      cloudResult = await uploadBufferToCloudinary(buffer, {
        folder,
        resourceType: isVideo ? 'video' : 'image',
      })
    } catch (err) {
      return reply.code(502).send({
        error: 'storage upload failed',
        detail: err instanceof Error ? err.message : 'unknown',
      })
    }

    const filename =
      decodeURIComponent(parsed.pathname.split('/').pop() ?? '') ||
      `import-${Date.now()}`

    const qualityWarnings = isVideo
      ? []
      : checkAssetQuality({
          width: cloudResult.width,
          height: cloudResult.height,
          mimeType,
          sizeBytes: cloudResult.bytes,
        })

    let asset
    try {
      asset = await prisma.digitalAsset.create({
        data: {
          label: body.label?.trim() || filename,
          type: isVideo ? 'video' : 'image',
          mimeType,
          sizeBytes: cloudResult.bytes,
          storageProvider: 'cloudinary',
          storageId: cloudResult.publicId,
          url: cloudResult.url,
          originalFilename: filename,
          contentHash,
          folderId: body.folderId ?? null,
          metadata: {
            width: cloudResult.width,
            height: cloudResult.height,
            format: cloudResult.format,
            durationSeconds: cloudResult.durationSeconds ?? null,
            resourceType: cloudResult.resourceType ?? null,
            qualityWarnings: qualityWarnings as unknown as object[],
            source: 'url_import',
            sourceUrl: parsed.toString(),
          },
        },
      })
    } catch (err: any) {
      if (err?.code === 'P2002') {
        const winner = await prisma.digitalAsset.findUnique({
          where: { workspace_contentHash: workspaceKey({ contentHash: contentHash }) },
        })
        if (winner)
          return reply.code(200).send({ asset: winner, dedup: true })
      }
      throw err
    }

    return reply.code(201).send({ asset })
  })

  // ── MC.3.2 — bulk ZIP upload (folder-preserving) ───────────

  fastify.post('/assets/upload-zip', async (request, reply) => {
    if (!isCloudinaryConfigured())
      return reply.code(503).send({ error: 'Storage is not configured.' })

    const part = await request.file({ limits: { fileSize: MAX_ZIP_BYTES } })
    if (!part) return reply.code(400).send({ error: 'no file uploaded' })

    if (
      part.mimetype !== 'application/zip' &&
      part.mimetype !== 'application/x-zip-compressed' &&
      !part.filename?.toLowerCase().endsWith('.zip')
    )
      return reply
        .code(400)
        .send({ error: 'expected a .zip archive' })

    const fields = part.fields as Record<
      string,
      { value: string } | undefined
    >
    const rootFolderId = fields?.rootFolderId?.value || null

    if (rootFolderId) {
      const root = await prisma.assetFolder.findUnique({
        where: { id: rootFolderId },
        select: { id: true },
      })
      if (!root)
        return reply
          .code(400)
          .send({ error: 'rootFolderId does not exist' })
    }

    let zipBuffer: Buffer
    try {
      zipBuffer = await part.toBuffer()
    } catch (err) {
      return reply.code(413).send({
        error: 'archive exceeds the size limit',
        detail: err instanceof Error ? err.message : 'unknown',
      })
    }
    if (zipBuffer.length > MAX_ZIP_BYTES)
      return reply
        .code(413)
        .send({ error: `archive exceeds the ${MAX_ZIP_BYTES} byte limit` })

    let zip: JSZip
    try {
      zip = await JSZip.loadAsync(zipBuffer)
    } catch (err) {
      return reply.code(400).send({
        error: 'archive could not be opened',
        detail: err instanceof Error ? err.message : 'unknown',
      })
    }

    // Walk entries: collect file rows (skip directory entries).
    interface ZipFileEntry {
      path: string
      filename: string
      folderPath: string[] // segments excluding the filename
      file: JSZip.JSZipObject
    }
    const entries: ZipFileEntry[] = []
    let entryCount = 0
    zip.forEach((path, zipObj) => {
      entryCount += 1
      if (zipObj.dir) return
      // Skip macOS junk + hidden files. The operator wouldn't expect
      // ".DS_Store" to land in their library.
      if (
        path.startsWith('__MACOSX/') ||
        path.split('/').some((seg) => seg.startsWith('.'))
      )
        return
      const segments = path.split('/').filter(Boolean)
      const filename = segments.pop() ?? path
      entries.push({
        path,
        filename,
        folderPath: segments,
        file: zipObj,
      })
    })

    if (entryCount > MAX_ZIP_ENTRIES)
      return reply.code(413).send({
        error: `archive has ${entryCount} entries — over the ${MAX_ZIP_ENTRIES} cap`,
      })

    // Resolve folder paths to AssetFolder ids. We cache (parentId,
    // segment) → id so each unique path only hits the DB once.
    type FolderKey = string
    const folderCache = new Map<FolderKey, string>()
    const keyOf = (parentId: string | null, segment: string) =>
      `${parentId ?? 'root'}::${segment}`

    const ensureFolder = async (
      segments: string[],
    ): Promise<string | null> => {
      let parentId: string | null = rootFolderId
      for (const segment of segments) {
        const cleanSegment = segment.trim()
        if (!cleanSegment) continue
        const key = keyOf(parentId, cleanSegment)
        const cached = folderCache.get(key)
        if (cached) {
          parentId = cached
          continue
        }
        // Look up an existing sibling first; create if missing.
        const existing = await prisma.assetFolder.findFirst({
          where: { parentId, name: cleanSegment },
          select: { id: true },
        })
        if (existing) {
          folderCache.set(key, existing.id)
          parentId = existing.id
          continue
        }
        const created = await prisma.assetFolder.create({
          data: { name: cleanSegment, parentId },
        })
        folderCache.set(key, created.id)
        parentId = created.id
      }
      return parentId
    }

    const summary = {
      total: entries.length,
      uploaded: 0,
      deduped: 0,
      skipped: 0,
      errors: [] as Array<{ path: string; error: string }>,
    }

    for (const entry of entries) {
      const ext = entry.filename.toLowerCase().split('.').pop()
      const mime =
        ext === 'jpg' || ext === 'jpeg'
          ? 'image/jpeg'
          : ext === 'png'
            ? 'image/png'
            : ext === 'webp'
              ? 'image/webp'
              : ext === 'gif'
                ? 'image/gif'
                : ext === 'avif'
                  ? 'image/avif'
                  : ext === 'tif' || ext === 'tiff'
                    ? 'image/tiff'
                    : null
      if (!mime || !UPLOAD_IMAGE_MIME_TYPES.has(mime)) {
        summary.skipped += 1
        continue
      }

      const buffer = await entry.file.async('nodebuffer')
      if (buffer.length > MAX_UPLOAD_BYTES) {
        summary.errors.push({
          path: entry.path,
          error: `file exceeds the ${MAX_UPLOAD_BYTES} byte per-file cap`,
        })
        continue
      }

      // Dedup short-circuit (MC.3.3 path).
      const contentHash = sha256Hex(buffer)
      const existing = await prisma.digitalAsset.findUnique({
        where: { workspace_contentHash: workspaceKey({ contentHash: contentHash }) },
        select: { id: true },
      })
      if (existing) {
        summary.deduped += 1
        continue
      }

      let folderId: string | null = rootFolderId
      try {
        folderId = await ensureFolder(entry.folderPath)
      } catch (err) {
        summary.errors.push({
          path: entry.path,
          error:
            err instanceof Error ? err.message : 'folder creation failed',
        })
        continue
      }

      const cloudFolder = folderId
        ? `marketing-content/${folderId}`
        : 'marketing-content/unfiled'

      try {
        const cloudResult = await uploadBufferToCloudinary(buffer, {
          folder: cloudFolder,
        })
        const qualityWarnings = checkAssetQuality({
          width: cloudResult.width,
          height: cloudResult.height,
          mimeType: mime,
          sizeBytes: cloudResult.bytes,
        })
        await prisma.digitalAsset.create({
          data: {
            label: entry.filename,
            type: 'image',
            mimeType: mime,
            sizeBytes: cloudResult.bytes,
            storageProvider: 'cloudinary',
            storageId: cloudResult.publicId,
            url: cloudResult.url,
            originalFilename: entry.filename,
            contentHash,
            folderId,
            metadata: {
              width: cloudResult.width,
              height: cloudResult.height,
              format: cloudResult.format,
              source: 'zip_import',
              zipPath: entry.path,
              qualityWarnings: qualityWarnings as unknown as object[],
            },
          },
        })
        summary.uploaded += 1
      } catch (err) {
        summary.errors.push({
          path: entry.path,
          error: err instanceof Error ? err.message : 'upload failed',
        })
      }
    }

    return reply.code(200).send({ summary })
  })

  // Move a set of assets to a folder (or to "unfiled" via folderId
  // null). Used by the bulk Move action; also handles single-asset
  // moves from the detail drawer.
  fastify.post('/assets/move', async (request, reply) => {
    const body = request.body as {
      assetIds?: string[]
      folderId?: string | null
    }
    if (!Array.isArray(body.assetIds) || body.assetIds.length === 0)
      return reply
        .code(400)
        .send({ error: 'assetIds array is required (1+ ids)' })

    if (body.folderId) {
      const folder = await prisma.assetFolder.findUnique({
        where: { id: body.folderId },
        select: { id: true },
      })
      if (!folder)
        return reply.code(400).send({ error: 'folderId does not exist' })
    }

    const updated = await prisma.digitalAsset.updateMany({
      where: { id: { in: body.assetIds } },
      data: { folderId: body.folderId ?? null },
    })
    return { moved: updated.count, folderId: body.folderId ?? null }
  })
}

export default assetsRoutes

