import { availableContentLanguages } from '../services/pim/market-languages.js'
import { currentFormulaWrite, registerFormulaRequestContext } from '../services/pim/mapping/formula-write-context.js'
import { inDatabaseTransaction } from '../lib/database-context.js'
/**
 * PIM B.1 — Global tab endpoints for /products/[id]/edit.
 *
 * Surfaces the "core truth" of a product as it appears on the new
 * Global tab: table-backed per-language content, identifiers, physical
 * dimensions, and technical attributes (categoryAttributes JSONB).
 *
 * Reads ProductTranslation with native-column fallback through the existing
 * resolver. Product.localizedContent is legacy, read-only and excluded here.
 *
 * Writes retain technical attributes and identifiers/physical fields.
 * Legacy localized writes are refused; LX.8 supplies the language writer.
 *
 * Routes (all mounted under /api):
 *   GET    /products/:id/global
 *   PATCH  /products/:id/global
 *   DELETE /products/:id/global/technical/:key
 */

import type { FastifyPluginAsync } from 'fastify'
import { isContentLocale, validateLocalizedPatch } from '../services/pim/localized-content.js'
import prisma from '../db.js'
import { globalContentLocales, type GlobalLocaleSlot as LocaleSlot } from '../services/pim/global-content.js'
import { resolveAttributes } from '../services/pim/attribute-resolver.js'
import { applyCatalogCascade } from '../services/pim/apply-mapping.service.js'
import { getMasterAttributeSchema } from '../services/pim/master-schema.service.js'
import { proposeImportFromChannel, proposeImportFromFlatFile } from '../services/pim/reverse-mapping.service.js'
import { getMasterCompleteness } from '../services/pim/master-completeness.service.js'
import { suggestMasterAttributes } from '../services/pim/master-ai-fill.service.js'

// ────────────────────────────────────────────────────────────────────
// Types
// ────────────────────────────────────────────────────────────────────

interface GlobalView {
  productId: string
  isVariant: boolean
  /** Per-locale resolved content. The shape mirrors what the Global
   *  tab renders directly — no extra parsing on the client. */
  locales: Record<string, LocaleSlot>
  identifiers: {
    brand: string | null
    manufacturer: string | null
    gtin: string | null
    upc: string | null
    ean: string | null
  }
  physical: {
    weightValue: number | null
    weightUnit: string | null
    dimLength: number | null
    dimWidth: number | null
    dimHeight: number | null
    dimUnit: string | null
  }
  /** categoryAttributes JSONB as-is. The UI renders this as a
   *  key/value list with add/edit/remove actions. */
  technical: Record<string, unknown>
}

interface PatchBody {
  dryRun?: boolean
  reset?: Record<string, string[]>
  expectedVersion?: number
  patch?: {
    [key: string]: any
    en?: Partial<LocaleSlot>
    it?: Partial<LocaleSlot>
    identifiers?: Partial<GlobalView['identifiers']>
    physical?: Partial<GlobalView['physical']>
    technical?: Record<string, unknown>
  }
}

// ────────────────────────────────────────────────────────────────────
// Helpers
// ────────────────────────────────────────────────────────────────────

/** Validate inbound patch shape. Returns array of human-readable
 *  errors (empty = valid). */
function validatePatch(body: unknown): string[] {
  const errors: string[] = []
  if (typeof body !== 'object' || body === null) return ['body must be an object']
  const b = body as Record<string, unknown>
  if (b.patch === undefined) return ['patch field is required']
  if (typeof b.patch !== 'object' || b.patch === null) return ['patch must be an object']

  const p = b.patch as Record<string, unknown>

  if (p.technical !== undefined && (typeof p.technical !== 'object' || p.technical === null || Array.isArray(p.technical))) {
    errors.push('patch.technical must be an object')
  }
  return errors
}

/** Merge incoming technical-attrs patch into existing categoryAttributes.
 *  Keys present in patch replace; keys absent are preserved; explicit
 *  null clears (matches existing override-data semantics). */
function mergeTechnical(
  current: unknown,
  patch: Record<string, unknown> | undefined,
): Record<string, unknown> {
  const base = (typeof current === 'object' && current !== null && !Array.isArray(current))
    ? (current as Record<string, unknown>)
    : {}
  if (!patch) return base
  return { ...base, ...patch }
}

// ────────────────────────────────────────────────────────────────────
// Route plugin
// ────────────────────────────────────────────────────────────────────

const pimGlobalRoutes: FastifyPluginAsync = async (fastify) => {
  await registerFormulaRequestContext(fastify, {})
  // ── GET /products/:id/global ────────────────────────────────────
  fastify.get<{ Params: { id: string } }>(
    '/products/:id/global',
    async (request, reply) => {
      const { id } = request.params

      const product = await prisma.product.findUnique({ where: { id }, include: { translations: true } })
      if (!product) {
        return reply.status(404).send({ error: 'Product not found' })
      }

      const parent = product.parentId
        ? await prisma.product.findUnique({ where: { id: product.parentId }, include: { translations: true } })
        : null

      const languages = await availableContentLanguages()
      const view: GlobalView = {
        productId: product.id,
        isVariant: product.parentId !== null,
        locales: globalContentLocales(product as any, parent as any, languages),
        identifiers: {
          brand: product.brand ?? null,
          manufacturer: product.manufacturer ?? null,
          gtin: product.gtin ?? null,
          upc: product.upc ?? null,
          ean: product.ean ?? null,
        },
        physical: {
          weightValue: product.weightValue == null ? null : Number(product.weightValue),
          weightUnit: product.weightUnit ?? null,
          dimLength: product.dimLength == null ? null : Number(product.dimLength),
          dimWidth: product.dimWidth == null ? null : Number(product.dimWidth),
          dimHeight: product.dimHeight == null ? null : Number(product.dimHeight),
          dimUnit: product.dimUnit ?? null,
        },
        technical: (product.categoryAttributes as Record<string, unknown> | null) ?? {},
      }

      return reply.send(view)
    },
  )

  // ── GET /products/:id/master-schema ─────────────────────────────
  // MA.1 — the attribute set the master SHOULD hold for its productType
  // (category attrs from the Amazon schema + mapping-rule sources), so the
  // Master tab can render typed fields instead of a blank key/value bag.
  fastify.get<{ Params: { id: string } }>(
    '/products/:id/master-schema',
    async (request, reply) => {
      try {
        const result = await getMasterAttributeSchema(request.params.id)
        return reply.send(result)
      } catch (err: any) {
        if (/not found/i.test(err?.message ?? '')) return reply.status(404).send({ error: err.message })
        request.log.error({ err }, 'master-schema failed')
        return reply.status(500).send({ error: err?.message ?? 'master-schema failed' })
      }
    },
  )

  // ── POST /products/:id/master/import-from-channel ────────────────
  // MA.3 — propose master values reverse-mapped from a channel listing (the
  // Amazon parent). Read-only; the caller applies accepted proposals via
  // PATCH /global.
  fastify.post<{ Params: { id: string }; Body: { channel?: string; marketplace?: string } }>(
    '/products/:id/master/import-from-channel',
    async (request, reply) => {
      const channel = (request.body?.channel ?? 'AMAZON').toUpperCase()
      const marketplace = request.body?.marketplace?.trim()
      if (!marketplace) return reply.status(400).send({ error: 'marketplace is required' })
      try {
        const result = await proposeImportFromChannel({ productId: request.params.id, channel, marketplace })
        return reply.send(result)
      } catch (err: any) {
        if (/not found|no .* listing/i.test(err?.message ?? '')) return reply.status(404).send({ error: err.message })
        request.log.error({ err }, 'import-from-channel failed')
        return reply.status(500).send({ error: err?.message ?? 'import-from-channel failed' })
      }
    },
  )

  // ── POST /products/:id/master/import-from-flat-file ─────────────
  // MA.7 — propose master values from the flat-file data (READ-ONLY; identity-
  // match against the master schema). Zero flat-file writes/code touched.
  fastify.post<{ Params: { id: string }; Body: { marketplace?: string } }>(
    '/products/:id/master/import-from-flat-file',
    async (request, reply) => {
      const marketplace = request.body?.marketplace?.trim()
      if (!marketplace) return reply.status(400).send({ error: 'marketplace is required' })
      try {
        const result = await proposeImportFromFlatFile({ productId: request.params.id, marketplace })
        return reply.send(result)
      } catch (err: any) {
        if (/not found|no .* flat-file/i.test(err?.message ?? '')) return reply.status(404).send({ error: err.message })
        request.log.error({ err }, 'import-from-flat-file failed')
        return reply.status(500).send({ error: err?.message ?? 'import-from-flat-file failed' })
      }
    },
  )

  // ── GET /products/:id/master/completeness ───────────────────────
  // MA.4 — overall + required-attribute completeness for governance.
  fastify.get<{ Params: { id: string } }>(
    '/products/:id/master/completeness',
    async (request, reply) => {
      try {
        return reply.send(await getMasterCompleteness(request.params.id))
      } catch (err: any) {
        if (/not found/i.test(err?.message ?? '')) return reply.status(404).send({ error: err.message })
        request.log.error({ err }, 'master completeness failed')
        return reply.status(500).send({ error: err?.message ?? 'completeness failed' })
      }
    },
  )

  // ── POST /products/:id/master/ai-fill ───────────────────────────
  // MA.5 — AI-infer empty master attributes from the product context.
  // Review-gated; caller applies accepted values via PATCH /global.
  fastify.post<{ Params: { id: string } }>(
    '/products/:id/master/ai-fill',
    async (request, reply) => {
      try {
        return reply.send(await suggestMasterAttributes(request.params.id))
      } catch (err: any) {
        if (/not found/i.test(err?.message ?? '')) return reply.status(404).send({ error: err.message })
        request.log.error({ err }, 'master ai-fill failed')
        return reply.status(500).send({ error: err?.message ?? 'ai-fill failed' })
      }
    },
  )

  // ── PATCH /products/:id/global ──────────────────────────────────
  // Technical/identifier/physical edits retain the existing atomic writer.
  // Localized JSON is frozen; its former write/reset/cascade path is retired.
  fastify.patch<{ Params: { id: string }; Body: PatchBody }>(
    '/products/:id/global',
    async (request, reply) => {
      const { id } = request.params
      const body = request.body

      const errors = validatePatch(body)
      if (errors.length > 0) {
        return reply.status(400).send({ error: 'invalid_patch', details: errors })
      }
      const language = Object.keys(body.patch!).find(isContentLocale)
      if (language || body.reset !== undefined) {
        return reply.code(409).send({ error: `Localized content${language ? ` (${language})` : ''} is legacy and read-only.`, field: 'localizedContent' })
      }
      const patch = body.patch!

      // Read current — needed for the merge. We could go straight to
      // a JSON_PATCH on Postgres but that complicates audit (we want
      // before+after for ProductEvent) and the row is small.
      const current = await prisma.product.findUnique({
        where: { id },
        select: {
          categoryAttributes: true,
          version: true,
        },
      })
      if (!current) return reply.status(404).send({ error: 'Product not found' })

      const localeErrors = validateLocalizedPatch(patch)
      if (localeErrors.length) return reply.code(400).send({ error: 'invalid_patch', details: localeErrors })
      if (body.expectedVersion !== undefined && (!Number.isSafeInteger(body.expectedVersion) || body.expectedVersion !== current.version)) {
        return reply.code(409).send({ error: 'This product changed. Reload and try again.', currentVersion: current.version })
      }
      const data: Record<string, unknown> = {}

      // Technical attributes (categoryAttributes JSONB)
      if (patch.technical) {
        data.categoryAttributes = mergeTechnical(current.categoryAttributes, patch.technical)
      }

      // Identifiers (direct columns for now — Phase B+ migrates these)
      if (patch.identifiers) {
        const idn = patch.identifiers
        if (idn.brand !== undefined) data.brand = idn.brand
        if (idn.manufacturer !== undefined) data.manufacturer = idn.manufacturer
        if (idn.gtin !== undefined) data.gtin = idn.gtin
        if (idn.upc !== undefined) data.upc = idn.upc
        if (idn.ean !== undefined) data.ean = idn.ean
      }

      // Physical (direct columns)
      if (patch.physical) {
        const ph = patch.physical
        if (ph.weightValue !== undefined) data.weightValue = ph.weightValue
        if (ph.weightUnit !== undefined) data.weightUnit = ph.weightUnit
        if (ph.dimLength !== undefined) data.dimLength = ph.dimLength
        if (ph.dimWidth !== undefined) data.dimWidth = ph.dimWidth
        if (ph.dimHeight !== undefined) data.dimHeight = ph.dimHeight
        if (ph.dimUnit !== undefined) data.dimUnit = ph.dimUnit
      }

      if (Object.keys(data).length === 0) {
        return reply.send({ ok: true, changed: false })
      }

      if (body.dryRun) return reply.send({ ok: true, changed: false })
      const formula = currentFormulaWrite(request.headers['x-nexus-formula-write'])
      if (formula && formula.productId !== id) return reply.code(400).send({ error: 'Formula destination does not match this product.' })
      const saved = await inDatabaseTransaction(prisma, async () => {
        const tx = prisma
        const updated = await tx.product.updateMany({ where: { id, version: current.version }, data: { ...data, version: { increment: 1 } } })
        if (!updated.count) return false
        if (formula) formula.results = await Promise.all(formula.operations?.() ?? [])
        return true
      })
      if (!saved) return reply.code(409).send({ error: 'This product changed. Reload and try again.' })

      // FM.8 — flag-gated auto-cascade: when master content/attributes
      // change, fan out to mapped channel coordinates via the catalog
      // mapping (translate + enqueue on the undo window). Default OFF
      // (FM_CASCADE_ON_SAVE !== 'on') → no behaviour change. Fire-and-
      // forget: the PATCH returns immediately; applyCatalogCascade enqueues
      // durably (OutboundSyncQueue) on its own.
      if (!formula && process.env.FM_CASCADE_ON_SAVE === 'on') {
        const changes: Record<string, unknown> = {}
        if (patch.technical) Object.assign(changes, patch.technical)
        // Localized content is refused above; only technical attributes reach this cascade.
        if (Object.keys(changes).length > 0) {
          void applyCatalogCascade({ productId: id, changes }, { reason: 'global-tab-save' }).catch(
            (err: unknown) => {
              request.log.warn(
                { err, productId: id },
                '[fm-cascade] auto-cascade after global save failed (non-blocking)',
              )
            },
          )
        }
      }

      let recalcError: string | undefined
      if (!formula) {
        try {
          const { reevaluateDependents } = await import('../services/pim/mapping/cell-formula.service.js')
          const changedFields = [...new Set([...Object.entries(patch).flatMap(([locale, slot]) => isContentLocale(locale) ? Object.keys(slot ?? {}).map(key => key.replace(/\[\d+\]$/, '')) : []), ...Object.values(body.reset ?? {}).flat()])]
          if (changedFields.includes('title')) changedFields.push('name')
          changedFields.push(...changedFields.filter(key => !['title', 'name', 'description', 'bulletPoints', 'keywords'].includes(key)).map(key => `attr_${key}`))
          await reevaluateDependents({ productId: id, changedFields, updatedBy: (request as any).authUser?.id, ip: request.ip })
        } catch (error) { recalcError = error instanceof Error ? error.message : String(error) }
      }
      return reply.send({ ok: true, changed: true, ...(recalcError ? { recalcError } : {}), currentVersion: current.version + 1, versionOf: 'product' })
    },
  )

  // ── GET /products/:id/channel-listing/:clId/inheritance ─────────
  // PIM B.2 — Per-SSOT-field inheritance state for one channel
  // listing. Surfaces to the operator: what value is currently
  // effective on this marketplace, what value would be inherited if
  // they reset, and whether an override is active.
  fastify.get<{ Params: { id: string; clId: string } }>(
    '/products/:id/channel-listing/:clId/inheritance',
    async (request, reply) => {
      const { id, clId } = request.params

      const [product, channelListing] = await Promise.all([
        prisma.product.findUnique({ where: { id } }),
        prisma.channelListing.findUnique({ where: { id: clId } }),
      ])
      if (!product) return reply.status(404).send({ error: 'Product not found' })
      if (!channelListing || channelListing.productId !== id) {
        return reply.status(404).send({ error: 'Channel listing not found for product' })
      }

      const parent = product.parentId
        ? await prisma.product.findUnique({ where: { id: product.parentId } })
        : null

      // Master (no channel context) gives the "what would I inherit
      // if I reset the override" value per SSOT field.
      const masterResolved = resolveAttributes({
        product: product as any,
        parent: parent as any,
      })
      // Effective with channel applied gives the current value.
      const effectiveResolved = resolveAttributes({
        product: product as any,
        parent: parent as any,
        channelListing: channelListing as any,
      })

      const ssot = ['title', 'description', 'price', 'quantity', 'bulletPoints'] as const
      const followFlagMap = {
        title: 'followMasterTitle',
        description: 'followMasterDescription',
        price: 'followMasterPrice',
        quantity: 'followMasterQuantity',
        bulletPoints: 'followMasterBulletPoints',
      } as const

      const fields: Record<string, {
        effective: unknown
        master: unknown
        isOverridden: boolean
        source: string | null
      }> = {}
      for (const key of ssot) {
        const followFlag = followFlagMap[key]
        const flagValue = (channelListing as unknown as Record<string, unknown>)[followFlag]
        const isOverridden = flagValue === false
        fields[key] = {
          effective: effectiveResolved[key]?.value ?? null,
          master: masterResolved[key]?.value ?? null,
          isOverridden,
          source: effectiveResolved[key]?.source ?? null,
        }
      }

      return reply.send({
        productId: id,
        channelListingId: clId,
        channel: channelListing.channel,
        marketplace: channelListing.marketplace,
        fields,
      })
    },
  )

  // ── POST /products/:id/channel-listing/:clId/reset ──────────────
  // PIM B.2 — Reset one (or all) SSOT fields to inherit from master.
  // Sets followMasterX=true + nulls xOverride. Idempotent: a field
  // already inheriting returns ok without a write.
  fastify.post<{
    Params: { id: string; clId: string }
    Body: { field: 'title' | 'description' | 'price' | 'quantity' | 'bulletPoints' | 'all' }
  }>(
    '/products/:id/channel-listing/:clId/reset',
    async (request, reply) => {
      const { id, clId } = request.params
      const { field } = request.body

      const VALID = new Set([
        'title',
        'description',
        'price',
        'quantity',
        'bulletPoints',
        'all',
      ])
      if (!field || !VALID.has(field)) {
        return reply
          .status(400)
          .send({ error: 'field must be one of title|description|price|quantity|bulletPoints|all' })
      }

      const cl = await prisma.channelListing.findUnique({ where: { id: clId } })
      if (!cl || cl.productId !== id) {
        return reply.status(404).send({ error: 'Channel listing not found for product' })
      }

      const data: Record<string, unknown> = {}
      const apply = (key: 'title' | 'description' | 'price' | 'quantity' | 'bulletPoints') => {
        switch (key) {
          case 'title':
            data.followMasterTitle = true
            data.titleOverride = null
            break
          case 'description':
            data.followMasterDescription = true
            data.descriptionOverride = null
            break
          case 'price':
            data.followMasterPrice = true
            data.priceOverride = null
            break
          case 'quantity':
            data.followMasterQuantity = true
            data.quantityOverride = null
            break
          case 'bulletPoints':
            data.followMasterBulletPoints = true
            data.bulletPointsOverride = []
            break
        }
      }
      if (field === 'all') {
        apply('title')
        apply('description')
        apply('price')
        apply('quantity')
        apply('bulletPoints')
      } else {
        apply(field)
      }

      const quantityWillChange =
        (field === 'quantity' || field === 'all') && cl.followMasterQuantity === false

      await prisma.channelListing.update({ where: { id: clId }, data })

      // A2 — journal followMasterQuantity toggle (best-effort, fail-open).
      if (quantityWillChange) {
        try {
          await prisma.auditLog.create({
            data: {
              entityType: 'ChannelListing',
              entityId: clId,
              action: 'update',
              userId: null,
              before: { followMasterQuantity: false },
              after: { followMasterQuantity: true },
              metadata: { field: 'followMasterQuantity', reason: 'reset' },
            },
          })
        } catch (auditErr) {
          request.log.warn({ err: auditErr, clId }, '[pim-global/reset] audit write failed (non-blocking)')
        }
      }

      return reply.send({ ok: true, field })
    },
  )

  // ── GET /products/:id/cascade-preview ───────────────────────────
  // PIM E.4 — Surface the fan-out of a master-field change. Returns
  // per-channel × per-marketplace listing counts that would inherit
  // (followMasterX=true) versus override (followMasterX=false), plus
  // the variant-child count for the product.
  //
  // The mapping is field-aware but not field-required: callers ask
  // "what does a master-level change touch?" and we return the
  // summary for each tracked SSOT field (title, description, price,
  // quantity, bulletPoints) so the UI can show "if you change title,
  // N listings inherit + M override; if you change price, …".
  fastify.get<{ Params: { id: string } }>(
    '/products/:id/cascade-preview',
    async (request, reply) => {
      const { id } = request.params

      const product = await prisma.product.findUnique({
        where: { id },
        select: {
          id: true,
          sku: true,
          parentId: true,
        },
      })
      if (!product) return reply.status(404).send({ error: 'Product not found' })

      // Variant children — direct count.
      const variantCount = await prisma.product.count({
        where: { parentId: id, deletedAt: null },
      })

      // Channel listings for this product.
      const listings = await prisma.channelListing.findMany({
        where: { productId: id },
        select: {
          id: true,
          channel: true,
          marketplace: true,
          listingStatus: true,
          followMasterTitle: true,
          followMasterDescription: true,
          followMasterPrice: true,
          followMasterQuantity: true,
          followMasterBulletPoints: true,
        },
      })

      // Per-(channel, marketplace) breakdown: counts of listings whose
      // followMasterX is true for each tracked SSOT field. Operator
      // sees "title: 7 listings inherit, 3 override" at a glance.
      type CellKey = string
      const cells = new Map<
        CellKey,
        {
          channel: string
          marketplace: string
          total: number
          inheritByField: Record<string, number>
          overrideByField: Record<string, number>
        }
      >()
      const trackedFields = [
        'title',
        'description',
        'price',
        'quantity',
        'bulletPoints',
      ] as const
      const followFlagMap: Record<(typeof trackedFields)[number], string> = {
        title: 'followMasterTitle',
        description: 'followMasterDescription',
        price: 'followMasterPrice',
        quantity: 'followMasterQuantity',
        bulletPoints: 'followMasterBulletPoints',
      }

      for (const l of listings) {
        const key = `${l.channel}::${l.marketplace}`
        const cell = cells.get(key) ?? {
          channel: l.channel,
          marketplace: l.marketplace,
          total: 0,
          inheritByField: Object.fromEntries(trackedFields.map((f) => [f, 0])),
          overrideByField: Object.fromEntries(trackedFields.map((f) => [f, 0])),
        }
        cell.total++
        for (const f of trackedFields) {
          const flagValue = (l as unknown as Record<string, unknown>)[followFlagMap[f]]
          // Default (undefined) === follow master (matches resolver convention).
          const follows = flagValue === undefined ? true : Boolean(flagValue)
          if (follows) cell.inheritByField[f]++
          else cell.overrideByField[f]++
        }
        cells.set(key, cell)
      }

      // Aggregate totals across all marketplaces.
      const totals: Record<string, { inherit: number; override: number }> = {}
      for (const f of trackedFields) totals[f] = { inherit: 0, override: 0 }
      for (const cell of cells.values()) {
        for (const f of trackedFields) {
          totals[f].inherit += cell.inheritByField[f]
          totals[f].override += cell.overrideByField[f]
        }
      }

      return reply.send({
        productId: id,
        productSku: product.sku,
        isVariant: product.parentId !== null,
        variantCount,
        totalListings: listings.length,
        marketplaceCount: cells.size,
        cells: Array.from(cells.values()).sort((a, b) => {
          if (a.channel !== b.channel) return a.channel.localeCompare(b.channel)
          return a.marketplace.localeCompare(b.marketplace)
        }),
        totals,
      })
    },
  )

  // ── DELETE /products/:id/global/technical/:key ──────────────────
  // Remove one key from categoryAttributes. Returns 200 with no
  // change when the key wasn't present (idempotent).
  fastify.delete<{ Params: { id: string; key: string } }>(
    '/products/:id/global/technical/:key',
    async (request, reply) => {
      const { id, key } = request.params

      const current = await prisma.product.findUnique({
        where: { id },
        select: { categoryAttributes: true },
      })
      if (!current) return reply.status(404).send({ error: 'Product not found' })

      const base = (typeof current.categoryAttributes === 'object'
        && current.categoryAttributes !== null
        && !Array.isArray(current.categoryAttributes))
        ? (current.categoryAttributes as Record<string, unknown>)
        : {}

      if (!(key in base)) {
        return reply.send({ ok: true, changed: false })
      }

      const next = { ...base }
      delete next[key]
      await prisma.product.update({
        where: { id },
        data: { categoryAttributes: next as unknown as object },
      })
      return reply.send({ ok: true, changed: true })
    },
  )
}

export default pimGlobalRoutes

apps/api/src/services/pim/resolver-shado.content:
/**
 * PIM A.2 — Resolver shadow-compare.
 *
 * Runs alongside legacy read paths to validate that
 * resolveAttributes() produces the same merged values that direct-
 * column reads do, for real production data shapes. Logs mismatches
 * as structured warnings; never alters the response.
 *
 * Activation: env flag PIM_RESOLVER_SHADOW=true. Off by default; when
 * off, the entry point is a noop and adds zero overhead.
 *
 * Compare contract (what we validate):
 *   1. categoryAttributes keys merge correctly from master → variant.
 *   2. localizedContent[locale] resolves with locale → en fallback.
 *   3. SSOT fields (title/description/price/quantity/bulletPoints)
 *      respect followMasterX: when true, return master/locale value;
 *      when false, return *Override (or legacy direct column).
 *
 * Three mismatch categories track real bugs vs expected "empty data":
 *   - both_present_differ:        resolver and legacy both returned
 *                                 a value but they differ. ACTUAL BUG.
 *   - resolver_absent_legacy_present:  data not yet in JSONB
 *                                 (localizedContent empty). EXPECTED
 *                                 until A.4 backfill runs; tracked so
 *                                 we know when to schedule that work.
 *   - resolver_present_legacy_absent:  resolver synthesised something
 *                                 from JSONB the legacy path doesn't
 *                                 know about. Worth investigating.
 */

import {
  resolveAttributes,
  type ProductLike,
  type ChannelListingLike,
  type ResolvedValue,
} from './attribute-resolver.js'

// ────────────────────────────────────────────────────────────────────
// Types + buffer
// ────────────────────────────────────────────────────────────────────

export type MismatchCategory =
  | 'both_present_differ'
  | 'resolver_absent_legacy_present'
  | 'resolver_present_legacy_absent'

export interface Mismatch {
  productId: string
  channelListingId: string | null
  key: string
  resolverValue: unknown
  legacyValue: unknown
  resolverSource: ResolvedValue['source'] | null
  category: MismatchCategory
  at: string
}

const BUFFER_CAP = 500
const buffer: Mismatch[] = []

export function recordMismatch(m: Mismatch): void {
  buffer.push(m)
  if (buffer.length > BUFFER_CAP) buffer.splice(0, buffer.length - BUFFER_CAP)
}

export interface ShadowStats {
  totalMismatches: number
  byCategory: Record<MismatchCategory, number>
  byKey: Record<string, number>
  byChannelListingId: Record<string, number>
  recent: Mismatch[]
}

export function getShadowStats(recentN: number = 20): ShadowStats {
  const byCategory: Record<MismatchCategory, number> = {
    both_present_differ: 0,
    resolver_absent_legacy_present: 0,
    resolver_present_legacy_absent: 0,
  }
  const byKey: Record<string, number> = {}
  const byChannelListingId: Record<string, number> = {}

  for (const m of buffer) {
    byCategory[m.category]++
    byKey[m.key] = (byKey[m.key] ?? 0) + 1
    if (m.channelListingId) {
      byChannelListingId[m.channelListingId] =
        (byChannelListingId[m.channelListingId] ?? 0) + 1
    }
  }

  return {
    totalMismatches: buffer.length,
    byCategory,
    byKey,
    byChannelListingId,
    recent: buffer.slice(-recentN),
  }
}

export function resetShadowBuffer(): void {
  buffer.length = 0
}

// ────────────────────────────────────────────────────────────────────
// Activation flag
// ────────────────────────────────────────────────────────────────────

export function isShadowEnabled(): boolean {
  return process.env.PIM_RESOLVER_SHADOW === 'true'
}

// ────────────────────────────────────────────────────────────────────
// Value equality (loose: number/Decimal/string-number all comparable)
// ────────────────────────────────────────────────────────────────────

export function valuesEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true
  if (a == null && b == null) return true
  if (a == null || b == null) return false

  // Numeric loose-equality — covers Prisma Decimal vs number vs numeric
  // string. The legacy path coerces with Number(); resolver may pass
  // through whichever shape was stored.
  const aNum = typeof a === 'number' ? a : Number(a)
  const bNum = typeof b === 'number' ? b : Number(b)
  if (!Number.isNaN(aNum) && !Number.isNaN(bNum) && (typeof a === 'number' || typeof b === 'number')) {
    return aNum === bNum
  }

  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((v, i) => valuesEqual(v, b[i]))
  }
  return false
}

function classify(resolverValue: unknown, legacyValue: unknown): MismatchCategory | null {
  const rPresent = resolverValue !== undefined && resolverValue !== null
  const lPresent = legacyValue !== undefined && legacyValue !== null
  if (!rPresent && !lPresent) return null
  if (rPresent && !lPresent) return 'resolver_present_legacy_absent'
  if (!rPresent && lPresent) return 'resolver_absent_legacy_present'
  if (valuesEqual(resolverValue, legacyValue)) return null
  return 'both_present_differ'
}

// ────────────────────────────────────────────────────────────────────
// Compare engines
// ────────────────────────────────────────────────────────────────────

/** Legacy read path → key/value expectations for SSOT fields. The
 *  resolver should match these. */
interface SsotExpectation {
  key: 'title' | 'description' | 'price' | 'quantity' | 'bulletPoints'
  /** What the legacy code returns for this field, given the entities. */
  legacyValue: unknown
}

function ssotExpectations(
  cl: ChannelListingLike,
  product: ProductLike,
  parent: ProductLike | null,
): SsotExpectation[] {
  // parent/product reserved for future SSOT cases that consult the
  // master layer (e.g., comparing localizedContent[locale].title).
  void parent
  void product

  const all: SsotExpectation[] = [
    {
      key: 'title',
      legacyValue: cl.followMasterTitle === false
        ? (cl.titleOverride ?? cl.title ?? null)
        : null, // legacy "master" title isn't in resolver scope yet — it lives in Product.name
    },
    {
      key: 'description',
      legacyValue: cl.followMasterDescription === false
        ? (cl.descriptionOverride ?? cl.description ?? null)
        : null,
    },
    {
      key: 'price',
      legacyValue: cl.followMasterPrice === false
        ? (cl.priceOverride ?? cl.price ?? null)
        : null,
    },
    {
      key: 'quantity',
      legacyValue: cl.followMasterQuantity === false
        ? (cl.quantityOverride ?? cl.quantity ?? null)
        : null,
    },
    {
      key: 'bulletPoints',
      legacyValue: cl.followMasterBulletPoints === false
        ? (cl.bulletPointsOverride ?? null)
        : null,
    },
  ]

  // We only compare when legacy expects an override (i.e., followMasterX === false).
  // When followMasterX === true, the legacy path falls through to master columns
  // (Product.name, Product.basePrice) which aren't in resolver scope yet — A.4
  // wires those in once localizedContent is backfilled. Suppressing those cases
  // here keeps the noise floor low while we ship A.2.
  return all.filter((e) => e.legacyValue !== null)
}

export interface ShadowCompareInput {
  product: ProductLike
  parent: ProductLike | null
  channelListings: ChannelListingLike[]
  locale?: string
  logger?: { warn: (obj: object, msg?: string) => void }
}

/**
 * Run the shadow compare for a product detail load. Mismatches go to
 * the buffer + the logger; the function returns the count of issues
 * recorded for this call (useful for callers that want to surface
 * "shadow-detected N issues" telemetry).
 */
/** A.4 — Keys the resolver synthesizes from legacy Product columns, and
 *  the legacy-column name that drives the expectation. Used by the
 *  shadow to validate synthesis against direct column reads. The
 *  expectation respects variant→parent precedence: if a variant has
 *  the column set, that wins; otherwise the parent's column does. */
const SYNTHESIZED_KEYS: Array<{
  resolverKey: string
  legacyCol:
    | 'name'
    | 'description'
    | 'bulletPoints'
    | 'keywords'
    | 'brand'
    | 'manufacturer'
    | 'basePrice'
}> = [
  { resolverKey: 'title',        legacyCol: 'name' },
  { resolverKey: 'description',  legacyCol: 'description' },
  { resolverKey: 'bulletPoints', legacyCol: 'bulletPoints' },
  { resolverKey: 'keywords',     legacyCol: 'keywords' },
  { resolverKey: 'brand',        legacyCol: 'brand' },
  { resolverKey: 'manufacturer', legacyCol: 'manufacturer' },
  { resolverKey: 'basePrice',    legacyCol: 'basePrice' },
]

/** Pick the legacy-column value that "wins" between variant and parent:
 *  variant value if non-empty, else parent value. Empty arrays count as
 *  absent so a variant with `bulletPoints: []` falls back to parent. */
function pickInheritedColumn(
  product: ProductLike,
  parent: ProductLike | null,
  col: string,
): unknown {
  const own = (product as unknown as Record<string, unknown>)[col]
  const ownPresent = own !== undefined && own !== null
    && !(Array.isArray(own) && own.length === 0)
  if (ownPresent) return own
  if (!parent) return null
  return (parent as unknown as Record<string, unknown>)[col]
}

export function shadowCompareProductRead(input: ShadowCompareInput): number {
  const { product, parent, channelListings, locale = 'en', logger } = input
  let recorded = 0

  // 1. Compare categoryAttributes keys (master + variant). For each
  //    key present in either layer, the resolver must return either
  //    the variant value (if set) or the parent value (if inheriting).
  const allCategoryKeys = new Set<string>([
    ...Object.keys(parent?.categoryAttributes ?? {}),
    ...Object.keys(product.categoryAttributes ?? {}),
  ])

  const productLevel = resolveAttributes({ product, parent, locale })

  for (const key of allCategoryKeys) {
    const ownValue = (product.categoryAttributes ?? {})[key]
    const parentValue = (parent?.categoryAttributes ?? {})[key]
    // Expected: variant value if set, else parent value.
    const expected = ownValue !== undefined ? ownValue : parentValue
    const resolved = productLevel[key]?.value

    const cat = classify(resolved, expected)
    if (!cat) continue

    const m: Mismatch = {
      productId: product.id,
      channelListingId: null,
      key,
      resolverValue: resolved,
      legacyValue: expected,
      resolverSource: productLevel[key]?.source ?? null,
      category: cat,
      at: new Date().toISOString(),
    }
    recordMismatch(m)
    logger?.warn(
      {
        productId: m.productId,
        key: m.key,
        resolver: m.resolverValue,
        legacy: m.legacyValue,
        source: m.resolverSource,
        category: m.category,
      },
      'pim-resolver-shadow-mismatch',
    )
    recorded++
  }

  // 1b. A.4 — Compare synthesized keys (title/description/bullet-
  //     Points/etc.) against the corresponding legacy columns.
  //     Synthesis fires only at the default locale ('en'); for other
  //     locales the resolver returns nothing for these keys and the
  //     legacy column is the "if you fell back to en, this is what
  //     you'd see" reference. We skip the compare for non-en locales
  //     since the resolver intentionally doesn't synthesize there.
  if (locale === 'en') {
    for (const { resolverKey, legacyCol } of SYNTHESIZED_KEYS) {
      const expected = pickInheritedColumn(product, parent, legacyCol)
      const resolved = productLevel[resolverKey]?.value
      const cat = classify(resolved, expected)
      if (!cat) continue

      const m: Mismatch = {
        productId: product.id,
        channelListingId: null,
        key: resolverKey,
        resolverValue: resolved,
        legacyValue: expected,
        resolverSource: productLevel[resolverKey]?.source ?? null,
        category: cat,
        at: new Date().toISOString(),
      }
      recordMismatch(m)
      logger?.warn(
        {
          productId: m.productId,
          key: m.key,
          resolver: m.resolverValue,
          legacy: m.legacyValue,
          source: m.resolverSource,
          category: m.category,
        },
        'pim-resolver-shadow-mismatch',
      )
      recorded++
    }
  }

  // 2. Compare SSOT fields per channel listing.
  for (const cl of channelListings) {
    const chanLevel = resolveAttributes({ product, parent, channelListing: cl, locale })
    for (const exp of ssotExpectations(cl, product, parent)) {
      const resolved = chanLevel[exp.key]?.value
      const cat = classify(resolved, exp.legacyValue)
      if (!cat) continue

      const m: Mismatch = {
        productId: product.id,
        channelListingId: cl.id,
        key: exp.key,
        resolverValue: resolved,
        legacyValue: exp.legacyValue,
        resolverSource: chanLevel[exp.key]?.source ?? null,
        category: cat,
        at: new Date().toISOString(),
      }
      recordMismatch(m)
      logger?.warn(
        {
          productId: m.productId,
          channelListingId: m.channelListingId,
          key: m.key,
          resolver: m.resolverValue,
          legacy: m.legacyValue,
          source: m.resolverSource,
          category: m.category,
        },
        'pim-resolver-shadow-mismatch',
      )
      recorded++
    }
  }

  return recorded
}

apps/api/src/services/pim/sheet-values.t.content:
/**
 * AM.1 — how a stored value becomes a CELL value, per shape. ONE copy, imported by the studio sheet,
 * the master sheet rows, readiness and the write router — the same derivation everywhere, so a slot
 * that reads `bulletPoints[2]` on one surface cannot read `bulletPoints[3]` on another.
 *
 * Pure and node-loadable. The store shapes it accepts (measured 2026-09-04):
 *   list    — a real array (`Product.bulletPoints String[]`, `bulletPointsOverride`), the wizard's
 *             legacy JSON-encoded string `'["a","b"]'` (`submission.service.ts:1259`), or a bare
 *             string (one item).
 *   measure — `{ value, unit }`, or a bare number (unit unknown — reported as null, never invented).
 *   scalar  — as stored.
 */
import type { SheetColumn } from './sheet-columns.service.js'

export type MeasureValue = { value: number | null; unit: string | null }

export function isBlankValue(v: unknown): boolean {
  if (v === null || v === undefined) return true
  if (typeof v === 'string') return v.trim() === ''
  if (Array.isArray(v)) return v.every(isBlankValue)
  if (typeof v === 'object') {
    const m = v as Partial<MeasureValue>
    if ('value' in m || 'unit' in m) return isBlankValue(m.value)
    return Object.keys(v as object).length === 0
  }
  return false
}

/** A stored list in any of its shapes → an array, or null when there is nothing. */
export function readListValue(raw: unknown): unknown[] | null {
  if (raw === null || raw === undefined) return null
  if (Array.isArray(raw)) return raw
  if (typeof raw === 'string') {
    const t = raw.trim()
    if (t === '') return null
    if (t.startsWith('[')) {
      try {
        const parsed = JSON.parse(t)
        if (Array.isArray(parsed)) return parsed
      } catch {
        /* a string that merely starts with "[" is one item */
      }
    }
    return [raw]
  }
  return [raw]
}

/** A stored measure in any of its shapes → `{ value, unit }`, or null when there is nothing. */
export function readMeasureValue(raw: unknown): MeasureValue | null {
  if (raw === null || raw === undefined || raw === '') return null
  if (typeof raw === 'object' && !Array.isArray(raw)) {
    const m = raw as Record<string, unknown>
    const value = m.value === null || m.value === undefined || m.value === '' ? null : Number(m.value)
    const unit = typeof m.unit === 'string' && m.unit ? m.unit : null
    if (value === null && unit === null) return null
    return { value: value !== null && Number.isFinite(value) ? value : null, unit }
  }
  const n = Number(raw)
  return Number.isFinite(n) ? { value: n, unit: null } : null
}

/**
 * Project a column's STORED value (the list, the measure, the scalar) onto what its cell shows:
 * slot `n` of a list is item `n-1`; a list column shows the array; a measure shows `{ value, unit }`.
 * `base` is the value stored under the column's base key (`slot.of` for a slot).
 */
export function projectCellValue(col: Pick<SheetColumn, 'shape' | 'slot'>, base: unknown): unknown {
  if (col.slot) {
    const list = readListValue(base)
    if (!list) return null
    const item = list[col.slot.index - 1]
    return item === undefined || item === null || item === '' ? null : item
  }
  if (col.shape === 'list') {
    const list = readListValue(base)
    if (!list) return null
    const kept = list.filter((v) => !isBlankValue(v))
    return kept
  }
  if (col.shape === 'measure') return readMeasureValue(base)
  return base === undefined ? null : base
}

/**
 * The inverse for a SLOT write: the stored array with slot `index` set to `value`. Positions are
 * kept (an emptied slot becomes `''`) so nothing the operator typed moves — the outbound writer
 * compacts empties away (Owner ruling 2026-09-05: no gating between slots).
 */
export function withSlotValue(current: unknown, index: number, value: unknown): string[] {
  const list = (readListValue(current) ?? []).map((v) => (v === null || v === undefined ? '' : String(v)))
  while (list.length < index) list.push('')
  list[index - 1] = value === null || value === undefined ? '' : String(value)
  // Trailing empties carry no information; keep interior holes.
  while (list.length > 0 && list[list.length - 1] === '') list.pop()
  return list
}

/** Read a `path` out of a JSON bag (`platformAttributes.itemSpecifics.Marca`). */
export function readPath(bag: unknown, path: string[]): unknown {
  let cur: unknown = bag
  for (const p of path) {
    if (!cur || typeof cur !== 'object') return undefined
    cur = (cur as Record<string, unknown>)[p]
  }
  return cur
}

/** `parseSlotField('bulletPoints[3]')` → `{ base: 'bulletPoints', index: 3 }`; null for a plain field. */
export function parseSlotField(field: string): { base: string; index: number } | null {
  const m = /^(.+)\[(\d+)\]$/.exec(field)
  if (!m) return null
  const index = Number(m[2])
  if (!Number.isInteger(index) || index < 1) return null
  return { base: m[1], index }
}

// ────────────────────────────────────────────────────────────────────
// Shape-aware WRITE coercion (AM.1) — the inverse of the projections above
// ────────────────────────────────────────────────────────────────────

/** The column facts a write needs; a subset of `SheetColumn` so the route can pass what it holds. */
export interface ShapeWriteFacts {
  maxLength?: number
  maxBytes?: number
  validation?: Record<string, unknown>
  kind?: string
  key?: string
  label?: string
  shape?: 'scalar' | 'list' | 'measure'
  cardinality?: { min: number; max: number | null }
  unitOptions?: string[]
  options?: string[]
  mode?: 'strict' | 'open'
}

export type ShapeWriteResult = { ok: true; value: unknown } | { ok: false; error: string }

const named = (f: ShapeWriteFacts) => f.label ?? f.key ?? 'this field'

/**
 * Turn an incoming cell value into the STORED shape for its column, or refuse with a sentence.
 * Never coerces across shapes: an array into a scalar, a bare number into a measure, or a string
 * into a list is refused rather than stringified — a `"a,b"` or `"[object Object]"` in the bag is
 * silent corruption (b0's reading of the route, 2026-09-05). `null`/`''`/`undefined` always means
 * CLEAR and is accepted for every shape. A legacy JSON-encoded array string (`'["a","b"]'`, the
 * wizard's L.2 encoding) is accepted for a list, because imports still carry it.
 */
export function coerceForShape(facts: ShapeWriteFacts | undefined, raw: unknown): ShapeWriteResult {
  const result = coerceShape(facts, raw)
  if (result.ok === false || result.value === null || result.value === undefined) return result
  const value = result.value
  const rules = facts?.validation ?? {}
  const number = (key: string): number | undefined => typeof rules[key] === 'number' && Number.isFinite(rules[key]) ? rules[key] as number : undefined
  const fail = (reason: string): ShapeWriteResult => ({ ok: false, error: `${named(facts ?? {})} ${reason}` })
  if (Array.isArray(value)) {
    if (number('minItems') !== undefined && value.length < number('minItems')!) return fail(`needs at least ${number('minItems')} values`)
    if (number('maxItems') !== undefined && value.length > number('maxItems')!) return fail(`takes at most ${number('maxItems')} values`)
    if (rules.uniqueItems === true && new Set(value).size !== value.length) return fail('requires distinct values')
  }
  const members = Array.isArray(value) ? value : facts?.shape === 'measure' ? [(value as MeasureValue).value] : [value]
  for (const member of members) {
    if (typeof member === 'string') {
      const max = facts?.maxLength ?? number('maxLength')
      if (max !== undefined && member.length > max) return fail(`takes at most ${max} characters`)
      if (number('minLength') !== undefined && member.length < number('minLength')!) return fail(`needs at least ${number('minLength')} characters`)
      if (facts?.maxBytes !== undefined && Buffer.byteLength(member, 'utf8') > facts.maxBytes) return fail(`takes at most ${facts.maxBytes} UTF-8 bytes`)
      if (typeof rules.pattern === 'string') {
        try { if (!new RegExp(rules.pattern, 'u').test(member)) return fail('does not match its configured format') }
        catch { return fail('has an invalid validation pattern; correct the attribute definition before saving') }
      }
    }
    if (typeof member === 'number') {
      const min = number('minimum') ?? number('min'), max = number('maximum') ?? number('max')
      if (min !== undefined && member < min) return fail(`must be at least ${min}`)
      if (max !== undefined && member > max) return fail(`must be at most ${max}`)
      if (number('exclusiveMinimum') !== undefined && member <= number('exclusiveMinimum')!) return fail(`must be greater than ${number('exclusiveMinimum')}`)
      if (number('exclusiveMaximum') !== undefined && member >= number('exclusiveMaximum')!) return fail(`must be less than ${number('exclusiveMaximum')}`)
      const multiple = number('multipleOf')
      if (multiple !== undefined && (multiple <= 0 || Math.abs(member / multiple - Math.round(member / multiple)) > 1e-8)) return fail(`must be a multiple of ${multiple}`)
    }
  }
  return result
}

function coerceShape(facts: ShapeWriteFacts | undefined, raw: unknown): ShapeWriteResult {
  if (raw === null || raw === undefined || raw === '') return { ok: true, value: null }
  if (Array.isArray(facts?.validation?.recordFields)) {
    let records: unknown = raw
    if (typeof raw === 'string') { try { records = JSON.parse(raw) } catch { return { ok: false, error: `${named(facts)} needs a list of structured records` } } }
    if (!Array.isArray(records) || records.some(row => !row || typeof row !== 'object' || Array.isArray(row))) return { ok: false, error: `${named(facts)} needs a list of structured records` }
    const result: Record<string, unknown>[] = []
    for (const [index, rawRow] of records.entries()) {
      const row = { ...rawRow }
      for (const field of facts.validation.recordFields as Array<Record<string, any>>) {
        if (!field.key || !['text', 'number', 'boolean', 'select'].includes(field.kind)) return { ok: false, error: `${named(facts)} has an invalid record definition` }
        const value = row[field.key]
        if (field.required && (value == null || value === '')) return { ok: false, error: `${named(facts)} record ${index + 1} needs ${field.label ?? field.key}` }
        if (value === undefined) continue
        const checked = coerceForShape({ label: `${named(facts)} record ${index + 1}: ${field.label ?? field.key}`, kind: field.kind,
          mode: field.options?.length ? 'strict' : 'open', options: field.options?.map((option: any) => option.value), validation: { minimum: field.min, maximum: field.max } }, value)
        if (!checked.ok) return checked
        row[field.key] = checked.value
      }
      result.push(row)
    }
    const unique = facts.validation.uniqueBy
    if (typeof unique === 'string' && new Set(result.map(row => row[unique])).size !== result.length) return { ok: false, error: `${named(facts)} needs distinct ${unique} values` }
    const sum = facts.validation.sum as { field?: string; total?: number } | undefined
    if (result.length && sum?.field && typeof sum.total === 'number' && Math.abs(result.reduce((total, row) => total + Number(row[sum.field!] ?? 0), 0) - sum.total) > 0.001) return { ok: false, error: `${named(facts)} ${sum.field} values must total ${sum.total}` }
    return { ok: true, value: result }
  }
  const shape = facts?.shape ?? 'scalar'

  if (shape === 'list') {
    let items: unknown[] | null = null
    if (Array.isArray(raw)) items = raw
    else if (typeof raw === 'string' && raw.trim().startsWith('[')) items = readListValue(raw)
    if (!items) {
      return { ok: false, error: `${named(facts!)} takes a LIST of values — send an array, not one value` }
    }
    if (items.some(item => item !== null && typeof item === 'object')) {
      return { ok: false, error: `${named(facts!)} takes simple values; structured records cannot be converted to text` }
    }
    const cleaned: unknown[] = []
    for (const item of items) {
      if (isBlankValue(item)) continue
      if (facts?.kind === 'number' || facts?.kind === 'boolean') {
        const member = coerceShape({ ...facts, shape: 'scalar' }, item)
        if (member.ok === false) return member
        cleaned.push(member.value)
      } else cleaned.push(String(item).trim())
    }
    const max = facts?.cardinality?.max ?? null
    if (max !== null && cleaned.length > max) {
      return { ok: false, error: `${cleaned.length} values — ${named(facts!)} takes at most ${max}` }
    }
    const min = facts?.cardinality?.min ?? 1
    if (cleaned.length < min) {
      return { ok: false, error: `${cleaned.length} value${cleaned.length === 1 ? '' : 's'} — ${named(facts!)} needs at least ${min}` }
    }
    if (facts?.mode === 'strict' && facts.options && facts.options.length > 0) {
      const off = cleaned.find((x) => !facts.options!.includes(String(x)))
      if (off !== undefined) return { ok: false, error: `"${off}" is not one of the allowed values for ${named(facts)}` }
    }
    return { ok: true, value: cleaned }
  }

  if (shape === 'measure') {
    if (typeof raw !== 'object' || Array.isArray(raw)) {
      return { ok: false, error: `${named(facts!)} is a measure — send { value, unit }, not a bare ${Array.isArray(raw) ? 'list' : typeof raw}` }
    }
    const m = raw as { value?: unknown; unit?: unknown }
    if (m.value != null && typeof m.value !== 'number' && typeof m.value !== 'string') {
      return { ok: false, error: `${named(facts!)} needs a numeric measure value` }
    }
    if (m.unit != null && typeof m.unit !== 'string') {
      return { ok: false, error: `${named(facts!)} needs a text unit code` }
    }
    let value: number | null = null
    if (m.value != null && !(typeof m.value === 'string' && m.value.trim() === '')) {
      const n = typeof m.value === 'number' ? m.value : Number(String(m.value).replace(',', '.'))
      if (!Number.isFinite(n)) return { ok: false, error: `"${String(m.value)}" is not a number for ${named(facts!)}` }
      value = n
    }
    const unit = typeof m.unit === 'string' && m.unit.trim() ? m.unit.trim() : null
    if (value === null && unit === null) return { ok: true, value: null }
    if (unit !== null && facts?.unitOptions && facts.unitOptions.length > 0 && !facts.unitOptions.includes(unit)) {
      return { ok: false, error: `unit "${unit}" is not one of ${facts.unitOptions.join(', ')} for ${named(facts)}` }
    }
    if (value !== null && unit === null && facts?.unitOptions && facts.unitOptions.length > 0) {
      return { ok: false, error: `${named(facts)} needs a unit (${facts.unitOptions.join(', ')})` }
    }
    return { ok: true, value: { value, unit } }
  }

  // scalar
  if (Array.isArray(raw)) return { ok: false, error: `${named(facts ?? {})} takes ONE value — a list was sent` }
  if (typeof raw === 'object') return { ok: false, error: `${named(facts ?? {})} takes ONE value — an object was sent` }
  let value = typeof raw === 'string' ? raw.trim() : raw
  if (value === '') return { ok: true, value: null }
  if (facts?.kind === 'number') {
    if (typeof value === 'boolean' || !Number.isFinite(Number(value))) return { ok: false, error: `${named(facts)} needs a number` }
    value = Number(value)
  }
  if (facts?.kind === 'boolean') {
    if (value === 'true') value = true
    if (value === 'false') value = false
    if (typeof value !== 'boolean') return { ok: false, error: `${named(facts)} needs Yes or No` }
  }
  if (facts?.mode === 'strict' && facts.options && facts.options.length > 0 && !facts.options.includes(String(value))) {
    return { ok: false, error: `"${String(value)}" is not one of the allowed values for ${named(facts)}` }
  }
  return { ok: true, value }
}

